-- LEVEL UP: juz40 «Информатика SMART желтоқсан» (5 ай 4 апта) тесттерін Информатика → Тесттер бөліміне қосу
-- Бір рет қана іске қосыңыз (қайта қосса, тесттер қайталанып қосылады).
do $$
declare sid text; sec text;
begin
  select id, coalesce((select x->>'id' from jsonb_array_elements(coalesce(sections,'[]'::jsonb)) x where x->>'kind'='test' order by (x->>'name' ilike '%тест%') desc limit 1),'tests')
    into sid, sec from public.subjects where name ilike 'Информатика%' order by length(name) limit 1;
  if sid is null then raise exception 'Информатика пәні табылмады'; end if;
end $$;
