  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Инфо | Mock test №1', '[{"q": "1. Танымал, еркін таратылатын ашық бастапқы коды бар ДҚБЖ", "options": ["A) Oracle", "B) IBM", "C) MySQL", "D) MS Access"], "answer": 2}, {"q": "2. Жасанды интеллектіні қолдану салаларына жатпайтын нұсқа", "options": ["A) білім беру", "B) ойын индустриясы", "C) медицина", "D) философия"], "answer": 3}, {"q": "3. Мейлінше нақты нәтиже алу үшін дұрыс және сапалы деректер көлемін жинақтау қажет машиналық оқыту құраушысы", "options": ["A) деректер", "B) ерекше белгілер", "C) алгоритм", "D) ерекше емес белгілер"], "answer": 0}, {"q": "4. Соңғы нәтижелі жиынтықта деректерді топтау арқылы жолдар санын шектейді", "options": ["A) From", "B) Having", "C) Where", "D) Group by"], "answer": 1}, {"q": "5. Автордың атын, жұмыстың атын, бөлімінің, тараудың, параграфтың қай бетте орналасқанын жол шетінде көрсететін анықтамалық жол", "options": ["A) навигация", "B) селектор", "C) колонтитул", "D) блок"], "answer": 2}, {"q": "6. ASCII кодтау кестесінің стандартты бөлігі", "options": ["A) 0-127", "B) 0-128", "C) 127-256", "D) 128-255"], "answer": 0}, {"q": "7. Excel-де бірнеше ұяшықтар тобын таңдау үшін жібермей басатын перне", "options": ["A) F4", "B) Enter", "C) Ctrl", "D) Tab"], "answer": 2}, {"q": "8. www.yandex.ru/posts/user.mp3 сілтемесі бойынша орналасқан", "options": ["A) бума", "B) веб-сайттың негізгі домені", "C) дыбыстық файл", "D) мәтіндік файл"], "answer": 2}, {"q": "9. Ақпаратты бір рет қана жазуға арналған оптикалық ақпарат тасымалдаушы", "options": ["A) қатқыл диск", "B) CD-RW", "C) флэш-жады", "D) CD-R"], "answer": 3}, {"q": "10. Тармақталған және қайталау әрекеттері жоқ, барлық әрекет тізбекпен, бірінен соң бірі табиғи реттілікпен бір реттен орындалатын алгоритмдік құрылым", "options": ["A) тармақталған алгоритмдер", "B) сызықтық алгоритмдер", "C) циклдік алгоритм", "D) кірістірілген алгоритм"], "answer": 1}, {"q": "11. MS Excel-де А10:А20 диапазонындағы сандардың қосындысын табу формуласын көрсетіңіз", "options": ["A) =СУММ(А10:А20)", "B) =СУММ(А10;А20)", "C) =СУММА(А10:А20)", "D) =СУММ(А10+А20)"], "answer": 0}, {"q": "12. Интернет желісіне қосылған әрбір пайдаланушының өзіндік қайталанбас физикалық адресі болады", "options": ["A) Доментік атауы", "B) URL-адрес", "C) Маска", "D) IP-адрес"], "answer": 3}, {"q": "13. Ұйым мен жеке тұлғаларға Интернет қызметтерін ұсынатын компания", "options": ["A) клиент", "B) абонент", "C) провайдер", "D) дистрибьютор"], "answer": 2}, {"q": "14. Алгоритмнің жұмыс істеу қабілетін тексеру, қателерін іздеу үшін қолданылатын программаны қадам-қадаммен орындау", "options": ["А) цикл", "В) трассировка", "C) тестілеу", "D) есептеу"], "answer": 1}, {"q": "15. Адамның психологиялық жай-күйін қамтамасыз ететін ортаның технологиялық бөлігіне тән қасиеті", "options": ["A) интерактивтілік", "B) мультимедиялық", "C) қолжетімділік", "D) иммерсивтілік"], "answer": 3}, {"q": "16. \"Егер a (7)-ден үлкен болса  немесе  b (-10)-нан кіші немесе тең болса, сонымен қатар c  (0)-ге тең болмаса, Код блогы орындалады.\" Код блогы орындалуы үшін a b c айнымалыларына берілетін мәндер", "options": ["A) a = 4, b = -11, c = 0", "B) a = 6, b = -9, c = 1", "C) a = 2, b = -12, c = 0", "D) a = 7, b = -10, c = 3"], "answer": 3}, {"q": "17. Төменде берілген параграфтың форматталуын анықтаңыз", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/06/07/lessons/quizzes/questions/images/d9bcbffc-7ad7-4fd0-9899-569fedb15b1e_Снимок-экрана —-2026-06-08-в 03.03.19.png", "options": ["A) color: black; background: white; font-weight: bold; font-size: 30px; border: 3px green solid;", "B) color: white; background: black; font-style: italic; font-size: 30px; border: 3px green solid;", "C) color: white; background: green; font-style: italic; font-size: 30px; border: 3px black solid;", "D) color: white; background: black; text-decoration: underline; font-size: 30px; border: 3px green solid;"], "answer": 1}, {"q": "18. Желідегі компьютерлер санын анықтау формуласы", "options": ["A) K=2N", "B) K=2N+1", "C) K=2N-1", "D) K=2N-2"], "answer": 3}, {"q": "19. Төмендегі кестедегі “Али” дерегі сақталған ұяшықтың дұрыс жазылуын көрсетіңіз", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/06/07/lessons/quizzes/questions/images/b2da6300-f24a-4650-9110-03d7806ed480_Снимок-экрана —-2026-06-08-в 03.03.24.png", "options": ["A) <td rowspan=\"2\">Али</td>", "B) <tr colspan=\"2\">Али</tr>", "C) <tr rowspan=\"2\">Али</tr>", "D) <td colspan=\"2\">Али</td>"], "answer": 0}, {"q": "20. C3 ұяшығындағы формуланы E5 ұяшығына көшірілсе, формуланың нәтижесін табыңыз", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/06/07/lessons/quizzes/questions/images/92929764-81fd-4070-934e-b9049afeb448_Снимок-экрана —-2026-06-08-в 03.05.17.png", "options": ["A) 21", "B) 28", "C) 48", "D) 18"], "answer": 1}, {"q": "21. Бірегей жұмыс ұстанымы бар, деректерді және осы деректерді өңдеу туралы ақпаратты сақтау технологиясы", "options": ["A) криптовалюта", "B) майнинг", "C) блокчейн", "D) IoT"], "answer": 2}, {"q": "22. Кез келген қатысушы жүйедегі транзакцияларды бақылай алады", "options": ["A) орталықсыздандыру", "B) толық ашықтық", "C) ымыраласу", "D) сенімділік"], "answer": 1}, {"q": "23. Қалалық мүлікті және қала көрсететін қызметтерді басқару тұжырымдамасы", "options": ["A) bigdata", "B) blockchain", "C) crowdfunding", "D) smartcity"], "answer": 3}, {"q": "24. Компьютер құрылғыларының жұмысын сипаттайтын кез келген логикалық функцияны іске асыратын электрондық құрылғы", "options": ["A) логикалық элемент", "B) АЛҚ", "C) логикалық схема", "D) басқару құрылғысы"], "answer": 2}, {"q": "25. Басқару тақтасын жасыруға мүмкіндік береді, true немесе false мәндерін қабылдайды", "options": ["A) HIDDEN", "B) BGCOLOR", "C) PLAY_LOOP=Z", "D) PLUGINSPACE"], "answer": 0}, {"q": "26. check функциясының қызметі", "options": ["A) Санның цифрларын қосады", "B) Санды жұп екендігін тексереді", "C) Санның палиндром екенін тексереді", "D) Санды кері айналдырады"], "answer": 2}, {"q": "27. transform(258) функциясының нәтижесі", "options": ["A) ''258''", "B) ''528''", "C) ''852''", "D) None"], "answer": 1}, {"q": "28. print(len(n)) нәтижесі", "options": ["A) 5", "B) 8", "C) 10", "D) 12"], "answer": 1}, {"q": "29. n = find(100, 1000) деп өзгертсек, print(len(n)) нәтижесі", "options": ["A) 15", "B) 18", "C) 20", "D) 25"], "answer": 2}, {"q": "30. transform(123) функциясының нәтижесі", "options": ["A) ''123''", "B) ''153''", "C) ''321''", "D) None"], "answer": 3}, {"q": "31. Массив генераторларының нәтижелерін сәйкестендіріңіз", "left": ["a = [i+1 for i in range(1, 5) if i >= 3]", "a = [i+2 for i in range(1, 4) if i <= 2]"], "options": ["a) 3 4 5", "b) 3 4", "c) 3 4 5 6", "d) 4 5"], "pairs": [3, 1]}, {"q": "32. Топология түрлерін анықтаңыз", "left": ["Желідегі барлық компьютерлердің орталық компьютерге немесе концентратор құрылғысына жалғануы", "Қарапайым желі түрі, сигнал шеңбер бойымен бір бағытта жүреді"], "options": ["a) шина", "b) ағаш", "c) жұлдызша тәріздес", "d) сақина"], "pairs": [2, 3]}, {"q": "33. <audio> тегінің атрибуттарын сәйкестендіріңіз", "left": ["controls", "preload"], "options": ["a) ойнату үшін файлдың жолын анықтайды", "b) аудиоға басқару тақтасын қосады", "c) оны қосқанда бет жүктелгеннен кейін файл бірден ойнай бастайды", "d) беттің өзін жүктеумен бірге файлды жүктеу үшін қолданылады"], "pairs": [1, 3]}, {"q": "34. Берілген HTML тізімдерінің тегтерін анықтаңыз", "left": ["I. сәлем\nII. әлем\nIII. оқушым", "A. алдағы\nB. ҰБТ-ға\nC. сәттілік!"], "options": ["a) <ol type = “1”> </ol>", "b) <ol type = “I”> </ol>", "c) <ol type = “a”> </ol>", "d) <ol type = “A”> </ol>"], "pairs": [1, 3]}, {"q": "35. MySQL-дің уақыт деректер типтерін сәйкестендіріңіз", "left": ["Timestamp", "Year"], "options": ["a) YYYY-MM-DD HH:MI:SS", "b) YYYY", "c) HH:MI:SS", "d) YYYY-MM-DD"], "pairs": [0, 1]}, {"q": "36. Ақпараттық қауіпсіздіктің маңызды қасиеті", "options": ["A) қолжетімділік", "B) желілік", "C) жүйелік", "D) статистикалық", "E) тұтастық", "F) құпиялылық"], "answers": [0, 4, 5]}, {"q": "37. Математикалық функциялар", "options": ["A) ord(), chr()", "B) max(), min()", "C) len(), int()", "D) sum(), pow()", "E) randint(), print()", "F) abs(), round()"], "answers": [1, 3, 5]}, {"q": "38. Он алтылық 28E санының екілік және сегіздік санау жүйесіндегі мәні", "options": ["A) 1010001110", "B) 1101001101", "C) 645", "D) 654", "E) 1216", "F) 1612"], "answers": [0, 4]}, {"q": "39. Python-дағы open() функциясының параметрі", "options": ["A) функция атауы", "B) айнымалы атауы", "C) файл өлшемі", "D) файл атауы", "E) файл түрі", "F) файлды ашу режимі"], "answers": [3, 5]}, {"q": "40. Y = a₀ + a₁x₁ +...+aₖxₖ сызықтық регрессия моделінің жалпы түрі", "options": ["A) a - факторлар саны", "B) x - регрессия коэффициенті", "C) a - регрессия коэффициенті", "D) k - әсер етуші айнымалылар", "E) х - әсер етуші айнымалылар", "F) k - факторлар саны"], "answers": [2, 4, 5]}]'::jsonb, now() + interval '0 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Инфо | Mock test №2', '[{"q": "1. Барлық тақырып тегтері осы тегтердің ішінде орналасуы керек", "options": ["A) <html>", "B) <head>", "C) <body>", "D) <title>"], "answer": 1}, {"q": "2. Берілген кодтың нәтижесін табыңыз\na = True\nb = True\nc = False\nres = not (a or b) or (c or a)\nprint(res)", "options": ["A) True", "B) False", "C) res", "D) 1"], "answer": 0}, {"q": "3. Excel-де МАКС() және МИН() функциялары", "options": ["A) Логикалық функциялар", "B) Мәтіндік функциялар", "C) Математикалық функциялар", "D) Статистикалық функциялар"], "answer": 3}, {"q": "4. Көлденең сызық сызатын тег", "options": ["A) <code>", "B) <q>", "C) <hr>", "D) <b>"], "answer": 2}, {"q": "5. Қазақстандағы цифландырудың бағыттарына жатпайтын бағыт", "options": ["A) Цифрлық мемлекетке өту", "B) Денсаулық сақтауды реформалау", "C) Экономика салаларын цифрландыру", "D) Цифрлық Жібек жолын іске асыру"], "answer": 1}, {"q": "6. Топология бұл", "options": ["A) бір-бірінен үлкен арақашықтықта орналасқан жергілікті желілердің бірігуі", "B) көптеген пайдаланушылар арасындағы қорларды орталық компьютер арқылы бір арнаға үйлестіру", "C) жерлігікті желідегі компьютерлердің бір-бірімен байланысу тәсілі", "D) ғаламдық желі арқылы ақпараттармен алмасу жүйесі"], "answer": 2}, {"q": "7. 32 символдық алфавиттің көмегімен жазылған, 20 символдан тұратын хабардың ақпараттық көлемін анықтаңыз", "options": ["A) 100 байт", "B) 120 бит", "C) 120 байт", "D) 100 бит"], "answer": 3}, {"q": "8. Суретте көрсетілген біріктіру түріне сәйкес сұраныс", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/06/08/lessons/quizzes/questions/images/e30610ee-a54d-4e08-a37c-3670bb714f15_Снимок-экрана —-2026-06-08-в 17.12.15.png", "options": ["A) SELECT * FROM table1 RIGHT JOIN table2 ON table1.id = table2.id", "B) SELECT * FROM table1 LEFT table2 ON table1.id = table2.id", "C) SELECT * FROM table1 LEFT JOIN table2", "D) SELECT * FROM table1 LEFT JOIN table2 ON table1.id = table2.id"], "answer": 3}, {"q": "9. НЕМЕСЕ логикалық амалының операторы", "options": ["A) +", "B) /", "C) !", "D) *"], "answer": 0}, {"q": "10. Компьютердегі барлық ақпарат екілік код түрінде сақталады", "options": ["A) Екілік кодтау қағидасы", "B) Жадтың біркелкілік қағидасы", "C) Адрестік қағида", "D) Программаны басқару қағидасы"], "answer": 0}, {"q": "11. Бірінші интеллектуалдық жүйе теориялық дәлелдеуге арналған программа", "options": ["A) Bitcoin", "B) Logic Theorist LT", "C) Crowdfunding", "D) VR"], "answer": 1}, {"q": "12. Смартфонның GPS функциясы жататын кеңейтілген шындық түрі", "options": ["A) суперпозиция негізінде кеңейтілген шындық", "B) проекциялар негізінде кеңейтілген шындық", "C) позициялық кеңейтілген шындық", "D) маркерленген негізінде кеңейтілген шындық"], "answer": 2}, {"q": "13. Кесте жиегінің енін пиксельдерде орнататын кесте тегінің атрибуты", "options": ["A) border=”...”", "B) width=”...”", "C) bgcolor=”URL”", "D) height=”...”"], "answer": 0}, {"q": "14. Процессордың жедел жадыға қатынау жиілігін азайтуға мүмкіндік береді", "options": ["A) қатқыл диск", "B) жедел жад", "C) тұрақты жад", "D) кэш-жады"], "answer": 3}, {"q": "15. Өрістер тігінен орналасып, жазбаның бір ғана түрі шығады", "options": ["A) кестелік", "B) бір бағанға", "C) таспалық", "D) тегістелген"], "answer": 1}, {"q": "16. Unicode-та кодтауға болатын символ", "options": ["A) 65365", "B) 16", "C) 65536", "D) 256"], "answer": 2}, {"q": "17. ASCII-дің кеңейтілген нұсқалары, бірақ олардың ішінен түрлі қосымша элементтер жойылып, баспаханалық символдар қосылған", "options": ["A) KOI-8", "B) ANSI", "C) KZ-1048", "D) Mac"], "answer": 1}, {"q": "18. “Мұғалімдер” мен “Оқушылар” кестелерінің дұрыс байланыс түрі", "options": ["A) Біреуден-біреуге", "B) Біреуден-көпке", "C) Көптен-біреуге", "D) Көптен-көпке"], "answer": 3}, {"q": "19. x айнымалысына 9 санын енгізгендегі нәтиже\nx = int(input())\nfor i in range(1, x, 2):\n    print(i, end = \" \")", "options": ["A) 1 2 3 4 5 6 7 8 9", "B) 1 3 5 7 9", "C) 1 3 5 7", "D) 2 4 6 8"], "answer": 2}, {"q": "20. Орындалуы керек қадам белгілі бір шарттың орындалуы немесе орындалмауына байланысты жүзеге асырылатын алгоритм", "options": ["A) көмекші", "B) циклдік", "C) сызықтық", "D) тармақталған"], "answer": 3}, {"q": "21. Пайдаланушыға виртуалды шындық арқылы объектілермен өзара әрекеттесуге мүмкіндік береді", "options": ["A) 3D жобалы VR", "B) Бірнеше қолданушы VR-і", "C) Қарапайым VR", "D) Позицилық VR"], "answer": 0}, {"q": "22. Компьютердің аппараттық және программалық құралдарының жұмысының тиімділігін диагностикалау, тестілеу және баптауға арналған программа", "options": ["A) CPU-Z (Central Processing Unit – Z)", "B) EVEREST Ultimate Edition", "C) VRAM", "D) POST"], "answer": 1}, {"q": "23. Объектіге бастапқы мәндерді орнатуға мүмкіндік береітн тегтер", "options": ["A) <embed>", "B) <object>", "C) <video>", "D) <param>"], "answer": 3}, {"q": "24. film кестесі берілген. Жас ерекшелігі PG-13 және ұзақтығы 60 минуттан аз болатын фильмдерді шығаратын сұраныс", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/06/08/lessons/quizzes/questions/images/541b3bf1-81cf-456e-988b-26e4ab27a58a_Снимок-экрана —-2026-06-08-в 17.14.46.png", "options": ["A) select * from film update rating = ''PG-13'' and length<60", "B) select * from film order by rating = ''PG-13'' and length<60", "C) select rating = ''PG-13'' and length<60", "D) select * from film where rating = ''PG-13'' and length<60"], "answer": 3}, {"q": "25. HTML тіліндегі тегтер CSS кодының ұсынылған стильі", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/06/08/lessons/quizzes/questions/images/d504a210-ef94-416b-beb6-8234396a7ad1_Снимок-экрана —-2026-06-08-в 17.15.04.png", "options": ["A) ішкі стиль", "B) құжат деңгейіндегі стиль", "C) сыртқы стиль", "D) байланысқан стиль"], "answer": 0}, {"q": "26. Фибоначчи тізбегінің алғашқы екі саны", "options": ["A) 1 2", "B) 0 1", "C) 1 1", "D) 0 2"], "answer": 1}, {"q": "27. fib(7) функциясының нәтижесі", "options": ["A) 8", "B) 13", "C) 21", "D) 34"], "answer": 1}, {"q": "28. print(len(n)) нәтижесі", "options": ["A) 10", "B) 11", "C) 12", "D) 13"], "answer": 2}, {"q": "29. n = find(50) деп өзгертсек, print(len(n)) нәтижесі", "options": ["A) 8", "B) 9", "C) 10", "D) 11"], "answer": 2}, {"q": "30. fib(10) функциясының нәтижесі", "options": ["A) 34", "B) 55", "C) 89", "D) 144"], "answer": 1}, {"q": "31. Сұрыптау алгоритмдерін сәйкестендіріңіз", "left": ["жылдам", "таңдау"], "options": ["a) Массивтегі ең кіші (ең үлкен) элементті тауып, оны сұрыпталмаған элементтердің бірінші тұрғанмен ауыстырады", "b) Массив элементтерінің арасынан тірек элемент таңдалады. Тірек элементтен кішілері сол жаққа, үлкендері оң жаққа реттеледі", "c) Массив элементтері реттелген және реттелмеген болып екіге бөлінеді. Реттелмеген бөлігіндегі элемент реттелген бөлігіне кірістіріп тексеру арқылы сұрыпталады", "d) Әр екі жұп элементті салыстырып шығады"], "pairs": [1, 0]}, {"q": "32. Python тізім әдістерін анықтаңыз", "left": ["a.extend(s)", "append(x)"], "options": ["a) тізімнің соңына х элементін қосады", "b) тізімдегі барлық элемент қосындысын шығарады", "c) x элементінің индексін қайтарады", "d) s тізіміндегі барлық элементтерді а тізіміндегі соңғы элементтерге тіркеп, жазады"], "pairs": [3, 0]}, {"q": "33. Хаттама нұсқаларын сәйкестендіріңіз", "left": ["IP v4 хаттамасындағы адрестер саны", "IP v6 хаттамасындағы адрестер саны"], "options": ["a) N = 2^16", "b) N = 2^32", "c) N = 2^64", "d) N = 2^128"], "pairs": [1, 3]}, {"q": "34. Желі топологияларына тән ерекшеліктерді анықтаңыз", "left": ["Сақина", "Жұлдыз"], "options": ["a) құрылғылар тікелей байланысу мүмкіндігі бар", "b) байланыс арнасынан бір компьютер істен шықса, желі жұмысын тоқтатады", "c) бірнеше компьютердің желімен бір кабель арқылы байланысады", "d) желідегі барлық компьютерлердің орталық компьютерге жалғанады"], "pairs": [1, 3]}, {"q": "35. Деректер қорындағы бұғаттау түрлерін сәйкестендіріңіз", "left": ["write lock", "read lock"], "options": ["a) деректерді өзгерту үшін серверден алынатын рұқсат", "b) деректерді оқу үшін серверден алынатын рұқсат", "c) деректерді жою үшін серверден алынатын рұқсат", "d) деректерді қалпына келтіру үшін серверден алынатын рұқсат"], "pairs": [0, 1]}, {"q": "36. Деректер қорындағы жазбаны жаңарту үшін қолданылатын SQL командасы", "options": ["A) INSERT INTO table", "B) ALTER TABLE table CHANGE", "C) ALTER TABLE table ADD", "D) UPDATE table SET", "E) ALTER TABLE table SET", "F) CREATE table CHANGE"], "answer": 3}, {"q": "37. Сілтеменің қайда апаратынын көрсету үшін қолданылатын атрибут", "options": ["A) гиперсілтеме", "B) anchor", "C) href", "D) id", "E) class", "F) src"], "answer": 2}, {"q": "38. img тегінің атрибуты бола алады", "options": ["A) href", "B) type", "C) src", "D) rel", "E) alt", "F) div"], "answers": [2, 4]}, {"q": "39. Python программалау тіліндегі цикл нұсқаулық(-тар)ы", "options": ["A) def", "B) for", "C) break", "D) while", "E) continue", "F) range"], "answers": [2, 4]}, {"q": "40. MySQL деректер қорында қолданылатын сандық деректердің өзгермелі нүктелер үшін деректер типтері", "options": ["A) double", "B) int", "C) mediumint", "D) float", "E) smallint", "F) tinytext"], "answers": [0, 3]}]'::jsonb, now() + interval '1 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№5.1 ТЕОРИУМ: Реляциондық деректер қоры', '[{"q": "1. Белгілі бір қасиеттері бойынша жинақталған үлкен көлемдегі ақпарат жиынтығы", "options": ["A) Атрибут", "B) Деректер базасы", "C) Мәтіндік құжат", "D) Программалық кешен"], "answer": 1}, {"q": "2. Деректерді ұйымдастыру түрі бойынша иерархиялық және желілік модельдердің жататын тобы", "options": ["A) Реляциялық", "B) Орталықтандырылған", "C) Реляциялық емес", "D) Таратылған"], "answer": 2}, {"q": "3. Бір нәрсенің ерекше белгісі, тұрақты қасиеті, заттың ажырамас бөлшегі.", "options": ["A) Атрибут", "B) Өріс", "C) Нысан", "D) Кесте"], "answer": 0}, {"q": "4. Деректер базасы кестесіндегі бағанның атауы", "options": ["A) Жазба", "B) Нысан", "C) Өріс", "D) Кілт"], "answer": 2}, {"q": "5. Кестедегі әрбір жазбаны бірегей түрде анықтайтын өріс", "options": ["A) Бастапқы өріс", "B) Кілттік өріс", "C) Сандық өріс", "D) Логикалық өріс"], "answer": 1}, {"q": "6. Мағлұматтары деректер базасында сақталатын ақпараттық жүйенің элементтері", "options": ["A) Атрибут", "B) Кесте", "C) Нысан", "D) Программа"], "answer": 2}, {"q": "7. Деректерді сақтау түрі бойынша бөлінуі", "options": ["A) Фактографиялық және құжаттық", "B) Реляциялық және желілік", "C) Орталықтандырылған және таратылған", "D) Иерархиялық және кестелік"], "answer": 2}, {"q": "8. Бірінші элементі басты болып саналады, қалғандары оған бағынышты деректер базасы", "options": ["A) Желілік", "B) Иерархиялық", "C) Реляциялық", "D) Кестелік"], "answer": 1}, {"q": "9. Жеке қолданушыға арналған деректер базасын жасақтаушы программалық жабдықтарға жатады", "options": ["A) Oracle", "B) Informix", "C) Microsoft Access", "D) DB2"], "answer": 2}, {"q": "10. Нысан, нақты оқиға немесе құбылыс саны", "options": ["A) Атрибут", "B) Жазба", "C) Баған", "D) Ұяшық"], "answer": 1}, {"q": "11. Көп қолданушылық деректер базасын құруға арналған программалық жабдықтарға жатады", "options": ["A) MySQL", "B) Visual FoxPro", "C) Oracle", "D) Microsoft Access"], "answer": 2}, {"q": "12. Нысанның, оқиға немесе құбылыстың атрибуттары", "options": ["A) Атрибут", "B) Жазба", "C) Баған", "D) Ұяшық"], "answer": 2}, {"q": "13. Деректер базасымен жұмыс істеуге арналған программалық жасақтама", "options": ["A) Операциялық жүйе", "B) Деректер базасын басқару жүйесі", "C) Мәтіндік редактор", "D) Реляциялық ДБ"], "answer": 1}, {"q": "14. ДББЖ-ның мүмкіндіктерінің бірі", "options": ["A) Компьютердің жадын тазарту", "B) Сұраныстар мен есептерді дайындау", "C) Антивирустық қорғаныс орнату", "D) Интернет жылдамдығын арттыру"], "answer": 1}, {"q": "15. Деректермен ыңғайлы жұмыс істеу үшін қолданылатын ДББЖ мүмкіндігі", "options": ["A) Архиватор", "B) Драйвер", "C) Форма құру", "D) Браузер"], "answer": 2}, {"q": "16. Алдыңғы элементтердің тәуелділігін есепке ала отырып құрылған база", "options": ["A) Реляциялық", "B) Иерархиялық", "C) Желілік", "D) Графикалық"], "answer": 1}, {"q": "17. Өзінің құрылымы бойынша аса күрделі және тораптар арасындағы еркін байланыстары бар деректер базасының графикалық моделі", "options": ["A) Желілік ДБ", "B) Кестелік ДБ", "C) Иерархиялық ДБ", "D) Фактографиялық ДБ"], "answer": 0}, {"q": "18. Пайдаланушылардың басым бөлігі қарапайым деректер базасын жасауды жөн көретін кестелік процессор", "options": ["A) Microsoft Word", "B) Microsoft Excel", "C) Paint", "D) PowerPoint"], "answer": 1}, {"q": "19. Нысанның қасиетінің мәндерін қамтитын кесте бағаны", "options": ["A) ДБ жазбасы", "B) ДБ өрісі", "C) Кілттік өріс", "D) Форма"], "answer": 1}, {"q": "20. Деректер қорының өрісінде орналасқан, белгілі қасиеті жазылған кестенің қатары", "options": ["A) ДБ жазбасы", "B) ДБ өрісі", "C) Нысан", "D) ДБ деректер типі"], "answer": 0}, {"q": "21. Деректер базасындағы «күні/уақыты» типіне жататын өріс", "options": ["A) Оқушының аты-жөні", "B) Телефон нөмірі", "C) Туған кезі", "D) Реттік нөмірі"], "answer": 2}, {"q": "22. Деректер қорында бірнеше типті деректердің бір типінде сақтайтын ақпараттар жиыны", "options": ["A) Деректер", "B) Жазба", "C) Файл", "D) Программа"], "answer": 0}, {"q": "23. Сақталған деректердің түрі бойынша бөлінуі", "options": ["A) Фактографиялық және құжаттық", "B) Реляциялық және желілік", "C) Орталықтандырылған және таратылған", "D) Иерархиялық және кестелік"], "answer": 0}, {"q": "24. Деректерді ұйымдастыру түрі бойынша бөлінуі", "options": ["A) Фактографиялық және құжаттық", "B) Реляциялық, иерархиялық және желілік", "C) Орталықтандырылған және таратылған", "D) Иерархиялық және құжаттық"], "answer": 1}, {"q": "25. Жазбалар мен өрістерден тұратын ДҚ-ның негізгі объектісі", "options": ["A) есеп", "B) макрос", "C) сұраныс", "D) кесте"], "answer": 3}, {"q": "26. Макрокомандалар жиынтығы", "options": ["A) есеп", "B) макрос", "C) сұраныс", "D) кесте"], "answer": 1}, {"q": "27. Кестелер мен сұраныстардағы деректерді ыңғайлы және көрнекі түрде экран бетіне басып шығару құралы", "options": ["A) есеп", "B) макрос", "C) сұраныс", "D) кесте"], "answer": 0}, {"q": "28. Деректерді бір немесе бірнеше кестелерден қолданушының қойған арты бойынша іріктеп алуға арналған құрал", "options": ["A) есеп", "B) макрос", "C) сұраныс", "D) кесте"], "answer": 2}, {"q": "29. Кестелер мен сұраныстардағы деректерді ыңғайлы түрде экранда бейнелейтін және оларды басқаратын құрал", "options": ["A) есеп", "B) модуль", "C) қалып", "D) кесте"], "answer": 2}, {"q": "30. Visual Basic тілінде жазылған ішкі программалар", "options": ["A) есеп", "B) модуль", "C) қалып", "D) кесте"], "answer": 1}]'::jsonb, now() + interval '2 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№5.2 ТЕОРИУМ: Bigdata, Реляциялық ДҚ', '[{"q": "1. Технологиялық инновациялар нәтижесінде пайда болған үлкен көлемдегі деректер", "options": ["A) SQL", "B) Bigdata", "C) Деректер базасы", "D) Желілік ДҚ"], "answer": 1}, {"q": "2. Негізгі үш операцияны орындауға арналған технологиялар жиынтығы", "options": ["A) SQL", "B) Bigdata", "C) Деректер базасы", "D) Желілік ДҚ"], "answer": 1}, {"q": "3. Өте үлкен көлемдегі әртүрлі құрылымдағы ақпараттарды жылдам өңдеу", "options": ["A) SQL", "B) Bigdata", "C) Деректер базасы", "D) Желілік ДҚ"], "answer": 1}, {"q": "4. Барлық есеп-қисап деректері бизнесті дамытуда үлкен рөл ойнайды", "options": ["A) Үшінші кезең – аналитика", "B) Төртінші кезең – даму", "C) Бірінші кезең – операциялар", "D) Екінші кезең мәліметтерді өзгерту"], "answer": 2}, {"q": "5. Жылдам аналитиканың көмегімен болжам жасау жүзеге асады", "options": ["A) Үшінші кезең – аналитика", "B) Төртінші кезең – даму", "C) Бірінші кезең – операциялар", "D) Екінші кезең мәліметтерді өзгерту"], "answer": 3}, {"q": "6. Бизнес аналитиканың арқасында қарқындай бастайды", "options": ["A) Үшінші кезең – аналитика", "B) Төртінші кезең – даму", "C) Бірінші кезең – операциялар", "D) Екінші кезең мәліметтерді өзгерту"], "answer": 1}, {"q": "7. Мұнда ақпараттарды талдап, өз сұрақтарымызға жауап таба аламыз", "options": ["A) Үшінші кезең – аналитика", "B) Төртінші кезең – даму", "C) Бірінші кезең – операциялар", "D) Екінші кезең мәліметтерді өзгерту"], "answer": 0}, {"q": "8. Деректердің арасындағы байланыстарды ұйымдастырудың түрлеріне жатпайды", "options": ["A) Иерархиялық", "B) Базалық", "C) Желілік", "D) Реляциялық"], "answer": 1}, {"q": "9. Егер бұл модельді графикалық түрде бейнелесек, жазықтықта бағыттауыш сызықтармен бейнеленген байланыстар шығады", "options": ["A) Иерархиялық", "B) Базалық", "C) Желілік", "D) Реляциялық"], "answer": 2}, {"q": "10. Кесте түрінде ұйымдастырылған деректер қоры", "options": ["A) Иерархиялық", "B) Базалық", "C) Желілік", "D) Реляциялық"], "answer": 3}, {"q": "11. Бұл – ең көп тараған деректер қоры", "options": ["A) Иерархиялық", "B) Базалық", "C) Желілік", "D) Реляциялық"], "answer": 3}, {"q": "12. Онда берілгендерді іздеп табу саты бойынша төмен бағытта жүргізіледі", "options": ["A) Иерархиялық", "B) Базалық", "C) Желілік", "D) Реляциялық"], "answer": 0}, {"q": "13. Объектілердің арасындағы өзара байланыс түрлері", "options": ["A) Иерархиялық", "B) Базалық", "C) Желілік", "D) Реляциялық"], "answer": 2}, {"q": "14. Әртүрлі кестедегі берілгендерді байланыстыру үшін, әрбір кестедегі жазбаның өзіндік жеке мәнін бере алатын өріс не өрістер жиынтығы", "options": ["A) сыртқы кілт", "B) негізгі кілт", "C) кестелік ДҚ", "D) реляциялық ДҚ"], "answer": 1}, {"q": "15. Үлкен деректер қоры ақпарат көлемі", "options": ["A) Гигабайттан терабайтқа дейін", "B) Петабайттан эксабайтқа дейін", "C) Гигабайттан эксабайтқа дейін", "D) Петабайттан терабайтқа дейін"], "answer": 1}, {"q": "16. Дәстүрлі деректер қоры ақпарат көлемі", "options": ["A) Гигабайттан терабайтқа дейін", "B) Петабайттан эксабайтқа дейін", "C) Гигабайттан эксабайтқа дейін", "D) Петабайттан терабайтқа дейін"], "answer": 0}, {"q": "17. Үлкен деректер қоры сақтау тәсілі", "options": ["A) Тік модель", "B) Көлденең модель", "C) Орталықтандырылған", "D) Орталықтандырылмаған"], "answer": 3}, {"q": "18. Дәстүрлі деректер қоры сақтау тәсілі", "options": ["A) Тік модель", "B) Көлденең модель", "C) Орталықтандырылған", "D) Орталықтандырылмаған"], "answer": 2}, {"q": "19. Cақталатын деректердің алуан түрлілігі – құрылымдалған (мысалы, кәсіпорындардың деректер қоры) және құрылымдалмаған", "options": ["A) Veracity", "B) Volume", "C) Variety", "D) Velocity"], "answer": 2}, {"q": "20. Нақты режимде деректерді жинақтау және өңдеу жылдамдығын үнемі арттыру", "options": ["A) Veracity", "B) Volume", "C) Variety", "D) Velocity"], "answer": 3}, {"q": "21. Бар деректердің дұрыстығы", "options": ["A) Veracity", "B) Volume", "C) Value", "D) Velocity"], "answer": 0}, {"q": "22. Жинақталған деректердің үлкен көлемін дәстүрлі әдістермен өңдеу және сақтау мүмкін емес, сондықтан жаңа, жетілдірілген талдау және басқару құралдарын енгізу қажет", "options": ["A) Veracity", "B) Volume", "C) Value", "D) Velocity"], "answer": 1}, {"q": "23. Ұйым үшін жинақталған ақпараттың пайдасы мен маңыздылығы", "options": ["A) Veracity", "B) Volume", "C) Value", "D) Velocity"], "answer": 2}, {"q": "24. Big Data ұсынатын артықшылықтар", "options": ["A) Деректердің құпиялылығы", "B) Үлкен көлемді деректерді сақтау", "C) Деректерді қорғау", "D) Әртүрлі көздерден деректерді жинау", "E) Инсайттар", "F) Өзгергіштік"], "answers": [1, 3, 4]}, {"q": "25. Big Data-ның қиыншылықтары", "options": ["A) Деректердің құпиялылығы", "B) Үлкен көлемді деректерді сақтау", "C) Деректерді қорғау", "D) Әртүрлі көздерден деректерді жинау", "E) Инсайттар", "F) Өзгергіштік"], "answers": [0, 2]}]'::jsonb, now() + interval '3 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№6 ТЕОРИУМ: JavaScript / Web-парақшаларды жасауда дайын скриптілерді қолдану', '[{"q": "1. Скрипт терминінің анықтамасы", "options": ["A) Интернеттегі құжаттарды белгілеудің стандартталған тілі", "B) Құжатты жүктеу кезінде немесе кейінірек орындалуы мүмкін клиенттік сценарийлерді қамтитын HTML түзету тілі", "C) Web-бет элементтерінің сыртқы көрінісін басқаруға арналған технология", "D) web-серверде орындалатын web-қосымшаларды (сценарийлерді) жазу үшін арнайы әзірленген программалау тілі"], "answer": 1}, {"q": "2. Нысанды бағытталған, императивті және функционалды стильдерді қабылдай алатын мультипарадигмалық программалау тілі", "options": ["A) JavaScript", "B) Php", "C) Html", "D) CSS"], "answer": 0}, {"q": "3. Деректер мен функциялар жиынынан тұратын бірыңғай конструкция", "options": ["A) Нысан", "B) Функция", "C) Интерфейс", "D) База"], "answer": 0}, {"q": "4. JavaScript негізі сәулеттік ерекшелігіне жатпайтын нұсқа", "options": ["A) динамикалық теру", "B) жылдам теру", "C) жадыны автоматты басқару", "D) әлсіз теру"], "answer": 1}, {"q": "5. Бетке JavaScript кодын қосу үшін қолданылатын тег", "options": ["A) <addscript></addscript>", "B) <body></body>", "C) <noscript></noscript>", "D) <script></script>"], "answer": 3}, {"q": "6. Үнемі жазбасы өзгеріп, жаңаланып отыратын сайт", "options": ["A) динамикалық сайт", "B) Php", "C) статикалық сайт", "D) Web-сайт"], "answer": 0}, {"q": "7. Динамикалық сайттар жазылатын программалау тілдері", "options": ["A) SQL", "B) Php", "C) Python", "D) Html", "E) Perl", "F) Css"], "answers": [1, 4]}, {"q": "8. JavaScript-тің басы мен соңын білдіретін түсіндірме тегтері", "options": ["A) #", "B) <!--", "C) {}", "D) **", "E) //- - >", "F) <?"], "answers": [1, 4]}, {"q": "9. Браузер Javascript қолдамаған жағдайда қолданылатын тег", "options": ["A) <addscript></addscript>", "B) <body></body>", "C) <noscript> </noscript>", "D) <script> </script>"], "answer": 2}, {"q": "10. Пайдаланушы тінтуірді элемент бойымен жылжытатын атрибут", "options": ["A) OnMouseOver", "B) OnMouseOut", "C) OnMouseDown", "D) OnKeyDown"], "answer": 0}, {"q": "11. Пішіндегі деректер Веб-серверге жіберетін атрибут", "options": ["A) OnSubmit", "B) OnBlur", "C) OnSelect", "D) OnFocus"], "answer": 0}, {"q": "12. Атрибуттарды сипаттамасымен сәйкестендіріңіз", "left": ["OnFocus", "OnBlur"], "options": ["A) Элемент енгізу фокусын алады", "B) Пішін тазаланады", "C) Элемент енгізу фокусын жоғалтады", "D) Пішіндегі деректер Веб-серверге жіберіледі"], "pairs": [0, 2]}, {"q": "13. Пернеге байланысты оқиғалар", "options": ["A) OnKeyPress", "B) OnKeyUp", "C) OnMouseOut", "D) OnSubmit", "E) OnSelect", "F) OnMouseOver"], "answers": [0, 1]}, {"q": "14. Ресурста іске асырылатын және порталдың функционалдығын кеңейтетін код", "options": ["A) Браузер", "B) Хост", "C) Сайт скрипті", "D) Веб сервер"], "answer": 2}, {"q": "15. JavaScript дескриптор атрибуттары", "options": ["A) language", "B) type", "C) alt", "D) href", "E) src", "F) a"], "answers": [0, 1, 4]}, {"q": "16. Pre форматтау тегі жаңа жолға көшіру үшін қолданылатын функция", "options": ["A) document.writeln()", "B) document.write()", "C) alert()", "D) prompt()"], "answer": 0}, {"q": "17. document.write() функция қызметі", "options": ["A) Хабарламамен модальді (диалогтық) терезені шығарады", "B) пайдаланушыны OK батырмасын басқанша күтеді", "C) OK/CANCEL батырмаларынан тұратын терезені шығарады", "D) Экран бетіне ақпаратты шығару үшін қолданылады"], "answer": 3}, {"q": "18. Функцияларды сипаттамасымен сәйкестендіріңіз", "left": ["prompt()", "confirm()"], "options": ["A) Пайдаланушы бір нәрсе енгізіп, OK батырмасын басу керек немесе CANCEL батырмасын және пернетақтадағы Esc пернесін басу арқылы енгізуді тоқтау керек", "B) Хабарламамен модальді (диалогтық) терезені шығарады және пайдаланушыны OK батырмасын басқанша күтеді", "C) Консолға ақпаратты шығару үшін қолданылады", "D) Екі батырмадан тұратын question сұрақ қойылған терезесін шығарады: OK/CANCEL. ОК батырмасын басқанда, true және CANCEL (Esc) басқанда false нәтижесі шығады"], "pairs": [0, 3]}, {"q": "19. Деректерді браузер консоліне шығаратын функция", "options": ["A) console.log()", "B) alert)", "C) document.write()", "D) prompt()"], "answer": 0}, {"q": "20. JavaScript кодын парақшаның қай жеріне енгізеді", "options": ["A) <head> және <body> бөлімдеріне", "B) Тек <java> бөліміне", "C) Тек <javascript> бөліміне", "D) Дұрыс жауабы жоқ"], "answer": 0}, {"q": "21.Сыртқы скрипт файлының кеңейтілімі", "options": ["A) .jsc", "B) .js", "C) .py", "D) .java"], "answer": 1}, {"q": "22. Сыртқы JavaScript кодын қосу мысалы", "options": ["A) <script src=\"myscript.js\"></script>", "B) <script file=\"myscript.js\">", "C) <js src=\"myscript.js\">", "D) <script href=\"myscript.js\">"], "answer": 0}, {"q": "23. HTML құжатқа JavaScript кодын кірістіру үшін қолданылатын синтаксис", "options": ["A) <script language=\"javascript\"> ... </script>", "B) <java> ... </java>", "C) <noscript> ... </noscript>", "D) <javascript language=\"javascript\"> ... </javascript>"], "answer": 0}, {"q": "24. JavaScript тілінде қолданылмайтын оператор", "options": ["A) elif", "B) const", "C) else if", "D) else"], "answer": 0}, {"q": "25. Басқа файлда жазылған скриптті парақшаға байланыстырудың дұрыс жолы", "options": ["A) <script ref=\"script.js\">", "B) <script href=\"script.js\">", "C) <script src=\"script.js\">", "D) <script link=\"script.js\">"], "answer": 2}, {"q": "26. JavaScript тілінде қолданылатын операторлар", "options": ["A) var", "B) let", "C) variable", "D) elif", "E) const", "F) function"], "answers": [0, 1, 4]}, {"q": "27. Деректі бүтін сандар типіне ауыстырады", "options": ["A) <script>", "B) parseFloat()", "C) <? ?>", "D) parseInt()"], "answer": 3}, {"q": "28. Браузер HTML құжатын ашуды аяқтайды", "options": ["A) OnSubmit", "B) OnBlur", "C) OnSelect", "D) OnLoad"], "answer": 3}, {"q": "29. Пішін тазаланады", "options": ["A) OnSubmit", "B) OnBlur", "C) OnSelect", "D) OnReset"], "answer": 3}, {"q": "30. Пайдаланушы пернені басып, қайта босатады", "options": ["A) OnFocus", "B) OnBlur", "C) OnKeyPress", "D) OnKeyDown"], "answer": 2}]'::jsonb, now() + interval '4 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№7 ТЕОРИУМ: Php / Web-парақша мен деректер қорының байланысын орнату', '[{"q": "1. Деректер қорымен динамикалық байланысты қолдайтын және мәліметтерді қарауға, өңдеуге, сонымен бірге базаға енгізуге мүмкіндік беретін диалогтық web-бет", "options": ["A) HTML", "B) PHP сценарийлері", "C) Деректер қоры бар web-беттер", "D) OpenServer"], "answer": 2}, {"q": "2. Қарапайым мәтіндік файлдар", "options": ["A) HTML", "B) PHP сценарийлері", "C) Деректер қоры бар web-беттер", "D) OpenServer"], "answer": 1}, {"q": "3. Web-сервер", "options": ["A) HTML", "B) MySQL", "C) Apache", "D) JavaScript"], "answer": 2}, {"q": "4. PHP скриптінде MySQL деректер қорынан деректерді алу үшін білу керек", "options": ["A) Apache-мен байланыс орнату", "B) пайдаланушының аты", "C) MS Access-пен байланыс орнату", "D) SQL командалар", "E) PHP сценарийлері", "F) хост"], "answers": [1, 3, 5]}, {"q": "5. HTML тегтерден PHP кодты әрқашан ажыратып отыру қажет символдар", "options": ["A) <$ ... $>", "B) <@ ... @>", "С) <? ... ?>", "D) <! ... //>"], "answer": 2}, {"q": "6. Барлық PHP айнымалылар басталатын символ", "options": ["A) <", "B) $", "C) ?", "D) #"], "answer": 1}, {"q": "7. Web-серверге әрі қарай PHP коды керектігі туралы хабарлайды", "options": ["A) $conn = mysql_connect(\"localhost\", \"root\", \"\")", "B) mysql_close($conn);", "C) ?>", "D) <?"], "answer": 3}, {"q": "8. Берілген жолдың мәнін анықтаңыз\nif ( !$conn)\n{\ndie (''Did not connect: '' . mysql_error());\n}", "options": ["A) Егер қосу жүргізілмесе, PHP себебін сипаттай отырып, хабарлама жібереді, ал PHP кодын өңдеу тоқтатылады", "B) PHP функциясы осы ақпаратты алады және оны ДҚБЖ-не қосу үшін пайдалануға тырысады", "C) Web-серверге әрі қарай PHP коды керектігі туралы хабарлайды", "D) Барлық деректер шығарылғаннан кейін, ДҚБЖ-не қосылу жабылады"], "answer": 0}, {"q": "9. Берілген жолдың мәнін анықтаңыз\n$conn = mysql_connect(\"localhost\", \"root\", \"\")", "options": ["A) Егер қосу жүргізілмесе, PHP себебін сипаттай отырып, хабарлама жібереді, ал PHP кодын өңдеу тоқтатылады", "B) PHP функциясы осы ақпаратты алады және оны ДҚБЖ-не қосу үшін пайдалануға тырысады", "C) Web-серверге әрі қарай PHP коды керектігі туралы хабарлайды", "D) Барлық деректер шығарылғаннан кейін, ДҚБЖ-не қосылу жабылады"], "answer": 1}, {"q": "10. Берілген жолдың мәнін анықтаңыз\nmysql_query (\"SET NAMES utf8\", $conn);", "options": ["A) Бұл жол ASCII кодында ұсыныла алмайтын символдармен берілген деректерді серверге жіберу үшін пайдаланылады", "B) Енді РНР синтаксисі web-бетте $result мәндерін шығару үшін қолданылады. While циклі деректердің соңына жеткенше жазбаларды таңдайды", "C) ДҚБЖ қосылуы сәтті өтті. Енді біз қажетті деректер қорын PHP-ге көрсетуіміз керек", "D) Барлық деректер шығарылғаннан кейін, ДҚБЖ-не қосылу жабылады"], "answer": 0}, {"q": "11. Берілген жолдың мәнін анықтаңыз\nmysql_select_db(\"kaz_mus_instruments\", $conn);", "options": ["A) Бұл жол ASCII кодында ұсыныла алмайтын символдармен берілген деректерді серверге жіберу үшін пайдаланылады", "B) Енді РНР синтаксисі web-бетте $result мәндерін шығару үшін қолданылады. While циклі деректердің соңына жеткенше жазбаларды таңдайды", "C) ДҚБЖ қосылуы сәтті өтті. Енді біз қажетті деректер қорын PHP-ге көрсетуіміз керек", "D) Барлық деректер шығарылғаннан кейін, ДҚБЖ-не қосылу жабылады"], "answer": 2}, {"q": "12. Берілген жолдың мәнін анықтаңыз\nwhile($row = mysql_fetch_array($result))", "options": ["A) Бұл жол ASCII кодында ұсыныла алмайтын символдармен берілген деректерді серверге жіберу үшін пайдаланылады", "B) Енді РНР синтаксисі web-бетте $result мәндерін шығару үшін қолданылады. While циклі деректердің соңына жеткенше жазбаларды таңдайды", "C) ДҚБЖ қосылуы сәтті өтті. Енді біз қажетті деректер қорын PHP-ге көрсетуіміз керек", "D) Барлық қайтарылатын жазбалар $result массивінде сақталады"], "answer": 1}, {"q": "13. Берілген жолдың мәнін анықтаңыз\n$result = mysql_query (\"SELECT * FROM producers\");", "options": ["A) Бұл жол ASCII кодында ұсыныла алмайтын символдармен берілген деректерді серверге жіберу үшін пайдаланылады", "B) Енді РНР синтаксисі web-бетте $result мәндерін шығару үшін қолданылады. While циклі деректердің соңына жеткенше жазбаларды таңдайды", "C) ДҚБЖ қосылуы сәтті өтті. Енді біз қажетті деректер қорын PHP-ге көрсетуіміз керек", "D) Барлық қайтарылатын жазбалар $result массивінде сақталады"], "answer": 3}, {"q": "14. Берілген жолдың мәнін анықтаңыз\n?>", "options": ["A) Бұл жол ASCII кодында ұсыныла алмайтын символдармен берілген деректерді серверге жіберу үшін пайдаланылады", "B) PHP сценарийі аяқталды", "C) Барлық деректер шығарылғаннан кейін, ДҚБЖ-не қосылу жабылады", "D) Барлық қайтарылатын жазбалар $result массивінде сақталады"], "answer": 1}, {"q": "15. Берілген жолдың мәнін анықтаңыз\nmysql_close ($conn);", "options": ["A) Бұл жол ASCII кодында ұсыныла алмайтын символдармен берілген деректерді серверге жіберу үшін пайдаланылады", "B) PHP сценарийі аяқталды", "C) Барлық деректер шығарылғаннан кейін, ДҚБЖ-не қосылу жабылады", "D) Барлық қайтарылатын жазбалар $result массивінде сақталады"], "answer": 2}, {"q": "16. PHP тілінде жазылған web-программа және MySQL жүйесін басқаруға арналған web-интерфейс", "options": ["A) Apache", "B) PhpMyAdmin", "C) SQL", "D) JavaScript"], "answer": 1}, {"q": "17. Осы интерфейс арқылы SQL операторларын қолмен жазып отырмай-ақ MySQL жүйесін оңай басқаруға болады", "options": ["A) Apache", "B) PhpMyAdmin", "C) SQL", "D) JavaScript"], "answer": 1}, {"q": "18. Ол көп ағынды сүйемелдеуі бар UNIX-серверлерде өз мүмкіндіктерін толық көрсете алу нәтижесінде өте үлкен көрсеткіштерге ие болуда", "options": ["A) Apache", "B) PhpMyAdmin", "C) MySQL", "D) JavaScript"], "answer": 2}, {"q": "19. Үлестірілген деректер қорының жылдам және мықты басқару жүйесі", "options": ["A) Apache", "B) PhpMyAdmin", "C) MySQL", "D) JavaScript"], "answer": 2}, {"q": "20. MySQL-дің мүмкіндіктерінен дұрыс емес тұжырымды анықтаңыз", "options": ["A) Күрделі және нәтижелі қауіпсіз жүйе", "B) Кестедегі жолақтар саны 50 млн-ға дейін жете алады", "C) Командалар өте тез орындалады", "D) Саны шектеусіз пайдаланушылар деректер қорымен бір уақытта жұмыс істей алады"], "answer": 0}, {"q": "21. Шаблон, контент және скриптерден тұратын динамикалық беттерден құралған, үнемі жазбасы өзгеріп, жаңаланып отыратын сайт", "options": ["A) Web-сайт", "B) HTML сайт", "C) Статикалық сайт", "D) Динамикалық сайт"], "answer": 3}, {"q": "22. Мүмкіндіктері мол әрі көп функционалды болғандықтан, ол барлық хостингтерге орнатылған", "options": ["A) Apache", "B) PHP", "C) MySQL", "D) JavaScript"], "answer": 1}, {"q": "23. Тек серверде ғана орындалатын скриптік тіл", "options": ["A) Apache", "B) PHP", "C) MySQL", "D) JavaScript"], "answer": 1}, {"q": "24. Шағын көп потокты деректер қорының сервері", "options": ["A) Apache", "B) PHP", "C) MySQL", "D) JavaScript"], "answer": 2}, {"q": "25. MySQL деректер базасындағы басқару жүйесінің серверіне қосылу орындалатын сыныбы", "options": ["A) dbname", "B) host", "C) mysqli", "D) php"], "answer": 2}, {"q": "26. Берілген скрипте қосылатын хост атауы\n$mysqli->real_connect(''host'', ''username'', ''passwd'', ''dbname'', ''port'')", "options": ["A) username", "B) passwd", "C) host", "D) dbname"], "answer": 2}, {"q": "27. Берілген скрипте сұраныс жасалатын деректер базасының атауы\n$mysqli->real_connect(''host'', ''username'', ''passwd'', ''dbname'', ''port'')", "options": ["A) username", "B) passwd", "C) host", "D) dbname"], "answer": 3}, {"q": "28. Берілген скрипте пайдаланушының аты\n$mysqli->real_connect(''host'', ''username'', ''passwd'', ''dbname'', ''port'')", "options": ["A) username", "B) passwd", "C) host", "D) dbname"], "answer": 0}, {"q": "29. Серверге қосылуды аяқтау үшін қолданылатын команда", "options": ["A) $mysqli->real_connect()", "B) $mysqli->close()", "C) mysqli_connect_errno()", "D) $mysqli = new mysqli ()"], "answer": 1}, {"q": "30. Осы күнгі серверлердің ішінде ең жылдам сервер болып есептеледі", "options": ["A) Apache", "B) PHP", "C) MySQL", "D) JavaScript"], "answer": 2}]'::jsonb, now() + interval '5 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№8 ТЕОРИУМ: Excel / Ақпараттық объектілерді құру және түрлендіру', '[{"q": "1. Деректерді жолдар мен бағандар қиылысында орналастыру арқылы ұсынудың тәсілі", "options": ["A) форма", "B) есеп", "C) формула", "D) кесте"], "answer": 3}, {"q": "2. Әдетте кестенің бірінші жолына жазылады", "options": ["A) бағандардың тақырыптары", "B) бағандардың типі", "C) жолдардың тақырыптары", "D) жолдардың типі"], "answer": 0}, {"q": "3. Microsoft Office кестесі қосымшаларының құрамындағы электрондық кестелермен жұмыс істеуге арналған программа", "options": ["A) MS Access", "B) MS Excel", "C) MS Word", "D) MS PowerPoint"], "answer": 1}, {"q": "4. Excel программасы жасайтын файлдың аты", "options": ["A) «Лист - Парақ»", "B) «Ячейка - Ұяшық»", "C) «Книга - Кітап»", "D) «Таблица - Кесте»"], "answer": 2}, {"q": "5. Excel-де файлдың кеңейтілімі", "left": ["2007 нұсқасына дейін", "2007 нұсқасынан бастап"], "options": ["A) .exc", "B) .excel", "C) .xls", "D) .xlsx"], "pairs": [2, 3]}, {"q": "6. Баған мен жолдың қиылысқан жеріндегі тіктөртбұрыш", "options": ["A) Кесте", "B) Ұяшық", "C) Формула", "D) Есеп"], "answer": 1}, {"q": "7. Ұяшық ішіне «=» белгісімен басталатын өрнек", "options": ["A) Сан", "B) Мәтін", "C) Формула", "D) Есеп"], "answer": 2}, {"q": "8. =А1*В1", "options": ["A) Сан", "B) Мәтін", "C) Формула", "D) Есеп"], "answer": 2}, {"q": "9. =А*В1+қосу", "options": ["A) Сан", "B) Мәтін", "C) Формула", "D) Есеп"], "answer": 1}, {"q": "10. 27-л", "options": ["A) Сан", "B) Мәтін", "C) Формула", "D) Есеп"], "answer": 1}, {"q": "11. Түрлі амалдарды орындау барысында амалдарды орындауға қатысатын ұяшықтардың адрестері автоматты түрде өзгеріп отырса, мұндай ұяшықтар", "options": ["A) аралас адрес", "B) статистикалық адрестеу", "C) абсолютті адрес", "D) салыстырмалы адрестеу"], "answer": 3}, {"q": "12. Ұяшықтармен жұмыс істеу барысында ұяшық адресі өзгермесе, мұндай ұяшықтар", "options": ["A) аралас адрес", "B) статистикалық адрестеу", "C) абсолютті адрес", "D) салыстырмалы адрестеу"], "answer": 2}, {"q": "13. Ұяшықтың абсолютті адресін көрсету үшін, сәйкесінше жол мен баған атауының алдына қойылатын белгі", "options": ["A) амперсанд", "B) доллар", "C) төменгі сызық", "D) тік жақшалар"], "answer": 1}, {"q": "14. Кестенің ұяшықтарына деректердің енгізе алатын типтері", "options": ["A) функция", "B) мәтін", "C) диаграмма", "D) формула", "E) сан", "F) есеп"], "answers": [1, 3, 4]}, {"q": "15. Кестені сандармен толтыруға, формулаларды автоматты қолдану мен есеп жүргізуге өте ыңғайлы функция", "options": ["A) Шартты форматтау", "B) Формула", "C) Автотолтыру", "D) Диаграмма"], "answer": 2}, {"q": "16. Ұяшықтардағы деректерді белгілі шарттар бойынша форматтау", "options": ["A) Шартты форматтау", "B) Формула", "C) Автотолтыру", "D) Диаграмма"], "answer": 0}, {"q": "17. Орналасқан мәндеріне қарай ұяшықтарды екі немесе үш түске бояу арқылы ерекшелеу", "options": ["A) Диаграмма", "B) Набор значков (Таңбалар жиынтығы)", "C) Цветовые шкалы (Түрлі түсті шекілдер)", "D) Гистограмма"], "answer": 2}, {"q": "18. Ұяшықтарға қойылатын таңбаларды көрсетеді", "options": ["A) Диаграмма", "B) Набор значков (Таңбалар жиынтығы)", "C) Цветовые шкалы (Түрлі түсті шекілдер)", "D) Гистограмма"], "answer": 1}, {"q": "19. Санды деректердің ерекшеліктерін визуалды қабылдауға ыңғайлы, түсінуге жеңіл етіп график түрінде ұсыну әдісі", "options": ["A) Диаграмма", "B) Набор значков (Таңбалар жиынтығы)", "C) Цветовые шкалы (Түрлі түсті шекілдер)", "D) Гистограмма"], "answer": 0}, {"q": "20. Microsoft Excel", "options": ["A) электронды кесте", "B) кестелік процессор", "C) мәтіндік процессор", "D) электронды бағдарлама"], "answer": 1}, {"q": "21. Екі немесе одан да көп ұяшықтардың жиынтығы", "options": ["A) адрес", "B) формула", "C) жол", "D) ауқым"], "answer": 3}, {"q": "22. Парақ ұяшықтарындағы мәтін мен формулаларды енгізу және өзгерту үшін қолданылатын панель", "options": ["A) Формула жолы", "B) Макет", "C) Сілтемелер", "D) Есеп"], "answer": 0}, {"q": "23. Екі ұяшықтағы мәтіндерді «желімдеу» үшін қолданылатын оператор", "options": ["A) амперсанд", "B) доллар", "C) төменгі сызық", "D) тік жақшалар"], "answer": 0}, {"q": "24. Тең емес логикалық операторы", "options": ["A) !=", "B) ?=", "C) <>", "D) =="], "answer": 2}, {"q": "25. Диаграмманың 3 элементі", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/04/16/lessons/quizzes/questions/images/51fe3d32-c570-4fc4-a686-b7f17bfd271a_Снимок-экрана-2026-04-16-в-18.54.58.png", "options": ["A) Диаграмма құру аймағы", "B) Диаграмма атауы", "C) Диаграмма легендасы", "D) Деректер қатары"], "answer": 2}, {"q": "26. Диаграмманың 7 элементі", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/04/16/lessons/quizzes/questions/images/4314d10d-3b0f-4f86-9a04-7d8656bfdea3_Снимок-экрана-2026-04-16-в-18.54.58.png", "options": ["A) Диаграмма құру аймағы", "B) Диаграмма торы", "C) Диаграмма көлденең осі", "D) Деректер қатары"], "answer": 1}, {"q": "27. Диаграмманың 4 элементі", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/04/16/lessons/quizzes/questions/images/9cf8e73a-8073-41ec-8d01-eae7424d4bbd_Снимок-экрана-2026-04-16-в-18.54.58.png", "options": ["A) Диаграмма легендасы", "B) Диаграмма торы", "C) Диаграмма көлденең осі", "D) Деректер қатары"], "answer": 3}, {"q": "28. Диаграмманың 5 элементі", "img": "https://files-api3.juz40-edu.kz/prod-bucket/METHODIST/subjects/6e172165-57c2-4b01-9fd1-70ccca7b96a7/2026/04/16/lessons/quizzes/questions/images/f6964eb1-18f2-43bc-8bb8-19dd5d7c56ff_Снимок-экрана-2026-04-16-в-18.54.58.png", "options": ["A) Диаграмма қатары", "B) Диаграмма торы", "C) Диаграмма көлденең осі", "D) Деректер вертикаль осі"], "answer": 3}, {"q": "29. Формуласы бар кез келген ұяшық", "options": ["A) салыстырмалы", "B) тәуелді", "C) абсолюттік", "D) функция"], "answer": 1}, {"q": "30. Формуланы жазу барысында қолданылатын объект адресі", "options": ["A) Ұяшық", "B) Сілтеме", "C) Формула", "D) Мәтін"], "answer": 1}, {"q": "31. Аргументтердің арифметикалық ортасын есептеу", "options": ["A) МИН()", "B) МАКС()", "C) СРЗНАЧ()", "D) СУММ()"], "answer": 2}, {"q": "32. Мәтіндегі бас әріптерді кіші әріптерге ауыстыруға мүмкіндік беретін функция", "options": ["A) ЗАМЕНИТЬ()", "B) СТРОЧН()", "C) ПСТР()", "D) ДЛСТР()"], "answer": 1}, {"q": "33. Мәтіндік жолдағы символдар санын есептейді", "options": ["A) ЗАМЕНИТЬ()", "B) СТРОЧН()", "C) ПСТР()", "D) ДЛСТР()"], "answer": 3}, {"q": "34. Берілген мәтіннен көрсетілген позициядан әріптерді қиып алуға мүмкіндік беретін функция", "options": ["A) ЗАМЕНИТЬ()", "B) СТРОЧН()", "C) ПСТР()", "D) ДЛСТР()"], "answer": 2}, {"q": "35. Мәтін жолының бір бөлігін басқа мәтіндік жолмен алмастырады", "options": ["A) ЗАМЕНИТЬ()", "B) СТРОЧН()", "C) ПСТР()", "D) ДЛСТР()"], "answer": 0}, {"q": "36. Көрсетілген ұяшыққа бір санды екіншісіне бөлуден қалған қалдықты шығаруға мүмкіндік береді", "options": ["A) ОКРУГЛ()", "B) ЦЕЛОЕ()", "C) ОСТАТ()", "D) КОРЕНЬ()"], "answer": 2}, {"q": "37. Санды көрсетілген дәлдікпен ең жақын разрядқа дейін дөңгелектейді", "options": ["A) ОКРУГЛ()", "B) ЦЕЛОЕ()", "C) ОСТАТ()", "D) КОРЕНЬ()"], "answer": 0}, {"q": "38. Санды ең жақын бүтін санға өрнектейді", "options": ["A) ЧАСТНОЕ()", "B) ЦЕЛОЕ()", "C) СТЕПЕНЬ()", "D) КОРЕНЬ()"], "answer": 1}, {"q": "39. Бөлу нәтижесінің бүтін бөлігін қылдықсыз береді", "options": ["A) ЧАСТНОЕ()", "B) ЦЕЛОЕ()", "C) СТЕПЕНЬ()", "D) КОРЕНЬ()"], "answer": 0}, {"q": "40. Санды дәрежеге шығарады", "options": ["A) ЧАСТНОЕ()", "B) ЦЕЛОЕ()", "C) СТЕПЕНЬ()", "D) КОРЕНЬ()"], "answer": 2}, {"q": "41. Квадрат түбірдің мәнін анықтайтын функция", "options": ["A) ЧАСТНОЕ()", "B) ЦЕЛОЕ()", "C) СТЕПЕНЬ()", "D) КОРЕНЬ()"], "answer": 3}, {"q": "42. Диаграммадағы қатарлар мәндерінің шартты белгіленуі", "options": ["A) График", "B) Макет", "C) Легенда", "D) Формула"], "answer": 2}, {"q": "43. (Жол бойынша абсолют) аралас адрес", "options": ["A) A1", "B) $A1", "C) A$1", "D) $A$1"], "answer": 2}, {"q": "44. ЕСЛИ()", "options": ["A) математикалық функция", "B) логикалық функция", "C) статистикалық функция", "D) мәтіндік функция"], "answer": 1}, {"q": "45. СЧЕТЕСЛИ()", "options": ["A) математикалық функция", "B) логикалық функция", "C) статистикалық функция", "D) мәтіндік функция"], "answer": 2}, {"q": "46. ЗНАК()", "options": ["A) математикалық функция", "B) логикалық функция", "C) статистикалық функция", "D) мәтіндік функция"], "answer": 0}, {"q": "47. СРЗНАЧ()", "options": ["A) математикалық функция", "B) логикалық функция", "C) статистикалық функция", "D) мәтіндік функция"], "answer": 2}, {"q": "48. Қате аргумент немесе оператор енгізілген", "options": ["A) Имя?", "B) Н/Д", "C) Дел/0!", "D) ЗНАЧ!"], "answer": 3}, {"q": "49. Мән берілмеген", "options": ["A) Имя?", "B) Н/Д", "C) Дел/0!", "D) ЗНАЧ!"], "answer": 1}, {"q": "50. Қиылыспайтын ұяшықтар аймағы көрсетілген", "options": ["A) Пусто!", "B) Н/Д", "C) Ссылка!", "D) Число!"], "answer": 0}, {"q": "51. Мәнді алу барысындағы қателік", "options": ["A) Пусто!", "B) Н/Д", "C) Ссылка!", "D) Число!"], "answer": 3}, {"q": "52. ПРЕДСКАЗ()", "options": ["A) математикалық функция", "B) логикалық функция", "C) статистикалық функция", "D) мәтіндік функция"], "answer": 2}]'::jsonb, now() + interval '6 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№9 ТЕОРИУМ: Компьютер құрылғылары', '[{"q": "1. Жедел есте сақтау құрылғысы", "options": ["A) ROM", "B) RAM", "C) HDD", "D) CD-R"], "answer": 1}, {"q": "2. Программалар өңдейтін деректерді жазу, оқу мен сақтауға арналған шағын көлемдегі жылдам есте сақтау құрылғысы", "options": ["A) ROM", "B) RAM", "C) HDD", "D) CD-R"], "answer": 1}, {"q": "3. Процессор жиі қолданылатын деректерді уақытша сақтау үшін қолданылатын шағын көлемді есте сақтауға арналған жад", "options": ["A) кэш", "B) ROM", "C) RAM", "D) қатқыл диск"], "answer": 0}, {"q": "4. Процессор мен одан жылдамдығы төмен жедел жад арасындағы өңдеу жылдамдығының айырмашылығын реттеу үшін қолданылатын жад", "options": ["A) кэш", "B) ROM", "C) RAM", "D) қатқыл диск"], "answer": 0}, {"q": "5. Тек оқуға арналған жад", "options": ["A) кэш", "B) ROM", "C) RAM", "D) қатқыл диск"], "answer": 1}, {"q": "6. Тұрақты жадтың маңызды микросхемасы", "options": ["A) POST", "B) HDD", "C) BIOS", "D) RAM"], "answer": 2}, {"q": "7. Енгізу-шығарудың базалық жүйесі", "options": ["A) POST", "B) HDD", "C) BIOS", "D) RAM"], "answer": 2}, {"q": "8. Компьютер құрылғыларының арасындағы өзара әрекетті ұйымдастырушы енгізу-шығару программаларының жиынтығы", "options": ["A) POST", "B) HDD", "C) BIOS", "D) RAM"], "answer": 2}, {"q": "9. Cыйымдылығы үлкен ақпарат жинақтаушы құрылғы", "options": ["A) қатқыл диск", "B) оптикалық диск", "C) кэш", "D) процессор"], "answer": 0}, {"q": "10. Магнитпен қапталған, біртұтас қабаттасқан бірнеше металдан немесе шыны дискілерден тұратын, көлемді ақпарат мөлшерін сақтай алатын дерек жинақтаушы", "options": ["A) қатқыл диск", "B) оптикалық диск", "C) кэш", "D) флеш жад"], "answer": 0}, {"q": "11. Жазылған мәліметтерді есте сақтай алатын микросхема (чип) түрінде жасалған жад түрі", "options": ["A) қатқыл диск", "B) оптикалық диск", "C) кэш", "D) флеш жад"], "answer": 3}, {"q": "12. Компьютер жадының басты міндеті", "options": ["A) ақпаратты өңдеу", "B) ақпаратты сақтау", "C) ақпаратты жіберу", "D) ақпаратты тарату"], "answer": 1}, {"q": "13. Компьютерлік есептеулерге арналған деректерді жазу, оқу және жылдам уақытша сақтау құрылғысы", "options": ["A) тұрақты жады", "B) жедел жады", "C) кэш жады", "D) қатқыл диск"], "answer": 1}, {"q": "14. Процессор мен жедел жады арасында деректер алмасу барысында қолданылады", "options": ["A) тұрақты жады", "B) жедел жады", "C) кэш жады", "D) қатқыл диск"], "answer": 2}, {"q": "15. Программалар мен ақпараттарды тасымалдаушы құралдар арқылы ұзақ уақыт сақтауға арналған құрылғы", "options": ["A) жедел жады", "B) ішкі жады", "C) сыртқы жады", "D) кэш жады"], "answer": 2}, {"q": "16. Қорғаныс қабаты бар иілгіш пластикалық дискі болып табылатын көлемі шағын ақпарат тасушылар", "options": ["A) қатқыл дискілер", "B) иілгіш дискілер", "C) флэш жады", "D) оптикалық дискілер"], "answer": 1}, {"q": "17. Заманауи ақпарат тасымалдаушы", "options": ["A) қатқыл дискілер", "B) иілгіш дискілер", "C) флэш жады", "D) оптикалық дискілер"], "answer": 2}, {"q": "18. Ақпаратты бір рет қана жазуға арналған оптикалық ақпарат тасымалдаушы", "options": ["A) CD-R және DVD-R", "B) CD-RW және DVD-RW", "C) қатқыл дискілер", "D) флэш жады"], "answer": 0}, {"q": "19. Компьютерді баптау мен оның конфигурациялары туралы деректерді ұзақ сақтауға негізделген", "options": ["A) кэш-жад", "B) CMOS-жад", "C) ROM", "D) VRAM"], "answer": 1}, {"q": "20. Кодталған бейнелер сақталатын жедел есте сақтау құрылғысының бір түрі", "options": ["A) кэш-жад", "B) CMOS-жад", "C) ROM", "D) VRAM"], "answer": 3}, {"q": "21. Жанды табиғат нысандары мен олардың өнеркәсіптік баламасын техникалық құрылғыларда және жүйелерде пайдаланатын қолданбалы ғылым", "options": ["A) биология", "B) информатика", "C) бионика", "D) инфографика"], "answer": 2}, {"q": "22. Орталық процессор, жедел жад микросхемалары, дыбыстық және бейнекарталар сияқты компьютердің ішкі құрылғылары орналастырылған негізгі мерлі тақша", "options": ["A) аналық тақша", "B) процессор", "C) шина", "D) чипсет"], "answer": 0}, {"q": "23. Көптеген жартылай өткізгішті элементтерден тұратын, компьютерде барлық есептеу мен ақпарат өңдеу жұмыстарын жүргізетін электронды микросхема", "options": ["A) аналық тақша", "B) процессор", "C) шина", "D) чипсет"], "answer": 1}, {"q": "24. Жиіліктің өлшем бірлігі", "options": ["A) Дж", "B) Мб", "C) Гц", "D) Вольт"], "answer": 2}, {"q": "25. Кернеуі, жиілігі, қуаты белгілі электр энергиясымен компьютерді жасайтын құрылғы", "options": ["A) аналық тақша", "B) қоректендіру блогы", "C) шина", "D) чипсет"], "answer": 1}, {"q": "26. Компьютер құрылғылары арасындағы электрлік сигналдарды басқаратын әрі олар арқылы деректер тасымалдауды жүзеге асыратын жалғастыру арналары", "options": ["A) аналық тақша", "B) қоректендіру блогы", "C) шина", "D) чипсет"], "answer": 2}, {"q": "27. Ұқсас міндет атқаратын микросхемалар жиынтығы", "options": ["A) аналық тақша", "B) қоректендіру блогы", "C) шина", "D) чипсет"], "answer": 3}, {"q": "28. Орталық процессордың шалғай құрылғылармен деректер алмастыру жұмысын жасақтайтын, аналық тақтада орналасқан микросхемалар жиынтығы", "options": ["A) аналық тақша", "B) сопроцессор", "C) шина", "D) чипсет"], "answer": 3}, {"q": "29. BIOS-тың ең соңғы нұсқасы", "options": ["A) AMIBIOS", "B) UEFI", "C) AwardBIOS", "D) PhoenixBIOS"], "answer": 1}, {"q": "30. Негізгі процессордың қызметтік мүмкіндігін толықтыратын мамандандырылған арнайы процессор", "options": ["A) аналық тақша", "B) сопроцессор", "C) слот кеңейтілімі", "D) чипсет"], "answer": 1}, {"q": "31. Компьютердің аналық тақташасындағы кеңейтілімнің алып-қосу ойығы", "options": ["A) аналық тақша", "B) сопроцессор", "C) слот кеңейтілімі", "D) чипсет"], "answer": 2}, {"q": "32. Компьютерге жоғары сапалы дыбыс шығаруға әрі жазуға мүмкіндік береді", "options": ["A) бейнекарта", "B) желілік тақша", "C) дыбыстық тақша", "D) енгізу-шығару порттары"], "answer": 2}, {"q": "33. Компьютерді компьютерлер желісіне қосуға мүмкіндік береді", "options": ["A) бейнекарта", "B) желілік тақша", "C) дыбыстық тақша", "D) енгізу-шығару порттары"], "answer": 1}, {"q": "34. Корпустың алдыңғы немесе артқы тақтасындағы ажыратқыштар", "options": ["A) бейнекарта", "B) желілік тақша", "C) дыбыстық тақша", "D) енгізу-шығару порттары"], "answer": 3}, {"q": "35. Программаға сәйкес операцияларды орындауға арналған компьютердің ең қымбат микросхемасы", "options": ["A) жедел жады", "B) кэш жады", "C) аналық тақша", "D) процессор"], "answer": 3}, {"q": "36. Бір тактте өңдей алатын биттер санымен анықталады", "options": ["A) процессордың тактілік жиілігі", "B) процессордың кэш-жады", "C) процессор разрядтылығы", "D) процессордың ядролар саны"], "answer": 2}, {"q": "37. Процессор бір секундта орындай алатын операциялардың саны", "options": ["A) процессордың тактілік жиілігі", "B) процессордың кэш-жады", "C) процессор разрядтылығы", "D) процессордың ядролар саны"], "answer": 0}, {"q": "38. Командалар мен процессорда өңделген ақпараттарды сақтайтын, процессор ішінде орналасқан жад ұяшықтары", "options": ["A) сопроцессор", "B) регисторлар", "C) процессор интерфейсі", "D) жүйелік шина"], "answer": 1}, {"q": "39. Барлық математикалық және логикалық операцияны орындайды", "options": ["A) сопроцессор", "B) басқару құрылғысы", "C) АЛҚ", "D) жүйелік шина"], "answer": 2}, {"q": "40. Процессордың командаларды тізбекпен орындауын қамтамасыз етеді", "options": ["A) сопроцессор", "B) басқару құрылғысы", "C) АЛҚ", "D) жүйелік шина"], "answer": 1}, {"q": "41. Қалқымалы үтірі бар сандарды өңдеуге арналған қосымша процессор элементі", "options": ["A) сопроцессор", "B) басқару құрылғысы", "C) АЛҚ", "D) жүйелік шина"], "answer": 0}, {"q": "42. Компьютердің барлық құрылғысын байланыстыратын ақпараттық магистраль", "options": ["A) сопроцессор", "B) басқару құрылғысы", "C) АЛҚ", "D) жүйелік шина"], "answer": 3}, {"q": "43. Орталық процессор", "options": ["A) GPU", "B) CPU", "C) Cache", "D) ROM"], "answer": 1}, {"q": "44. Графиканы өңдеуге арналған процессор", "options": ["A) GPU", "B) CPU", "C) Cache", "D) ROM"], "answer": 0}, {"q": "45. Процессордағы транзистор өлшемі", "options": ["A) техпроцесс", "B) микрон", "C) нанометр", "D) герц"], "answer": 0}, {"q": "46. Метрдің миллионнан бір бөлігі, яғни 10⁻⁶ метрге тең", "options": ["A) техпроцесс", "B) микрон", "C) нанометр", "D) герц"], "answer": 1}, {"q": "47. Процессордың машиналық сөз сақталатын ұяшық жады", "options": ["A) регистр", "B) кэш", "C) разрядтылық", "D) такт"], "answer": 0}, {"q": "48. Компьютердің ең негізгі құрылғысы", "options": ["A) жүйелік блок", "B) монитор", "C) пернетақта", "D) тінтуір"], "answer": 0}, {"q": "49. Компьютердің экранына ақпарат шығаруға арналған құрылғы", "options": ["A) жүйелік блок", "B) монитор", "C) пернетақта", "D) тінтуір"], "answer": 1}, {"q": "50. Монитор, принтер, плоттер, динамиктер, құлаққап", "options": ["A) шығару құрылғылары", "B) енгізу құрылғылары", "C) ақпарат алмасу құрылғылары", "D) сақтау құрылғылары"], "answer": 0}, {"q": "51. Түрлі көлемдегі флеш-жад құрылғылары", "options": ["A) шығару құрылғылары", "B) енгізу құрылғылары", "C) ақпарат алмасу құрылғылары", "D) сақтау құрылғылары"], "answer": 3}, {"q": "52. Барлық программалық құралдардың жиынтығы мен олардың қажет ететін, компьютерде қолданылатын деректері", "options": ["A) hardware", "B) software", "C) freeware", "D) open source"], "answer": 1}, {"q": "53. Бұл программаларды тегін пайдалануға, өзгертуге және таратуға болады", "options": ["A) шектеулі-тегін программалық жабдықтар", "B) еркін қолданыстағы программалық жабдықтар", "C) тегін программалық жабдықтар", "D) коммерциялық программалық жабдықтар"], "answer": 2}, {"q": "54. Бұл программаларды коммерциялық мақсаттан тыс, тегін қолдануға болады", "options": ["A) shareware", "B) freeware", "C) open source", "D) hardware"], "answer": 1}, {"q": "55. Бұл программаларды пайдалануда кейбір функциялардың қызметі орындалмайды", "options": ["A) shareware", "B) freeware", "C) open source", "D) hardware"], "answer": 0}, {"q": "56. Бұл программаларды пайдалану үшін әрбір көшірмеге ақы төленеді, программа кодын өзгертуге және деректерді ауыстыруға тыйым салынады", "options": ["A) шектеулі-тегін программалық жабдықтар", "B) еркін қолданыстағы программалық жабдықтар", "C) тегін программалық жабдықтар", "D) коммерциялық программалық жабдықтар"], "answer": 3}, {"q": "57. Компьютердің аппараттық және программалық құралдарының жұмысының тиімділігін диагностикалау, тестілеу және баптауға арналған программа", "options": ["A) BIOS", "B) CPU-Z", "C) EVEREST Ultimate Edition", "D) POST"], "answer": 2}, {"q": "58. Қатқыл дискіден басқа, орталық процессордың, аналық тақшаның және BIOS, жедел жадының, бейнекартаның техникалық сипаттамасын анықтайтын программа", "options": ["A) BIOS", "B) CPU-Z", "C) EVEREST Ultimate Edition", "D) POST"], "answer": 1}, {"q": "59. Компьютерлік жүйенің жұмыс істеуін жалпы басқаруды және оның техникалық қызмет көрсету функцияларын орындауды қамтамасыз ететін программалар жиынтығы", "options": ["A) Инструменталдық программалық жасақтама", "B) Қолданбалы программалық жасақтама", "C) Лицензияланған программалар", "D) Жүйелік программалық жасақтама"], "answer": 3}, {"q": "60. Программалау тілінде компьютерге арналған жаңа программаларды құруға ықпал етеді", "options": ["A) Инструменталдық программалық жасақтама", "B) Қолданбалы программалық жасақтама", "C) Лицензияланған программалар", "D) Жүйелік программалық жасақтама"], "answer": 0}, {"q": "61. Компьютерді пайдаланушыларға арналған белгілі бір мәселелерді шешуге көмектесетін программалар жиынтығы", "options": ["A) Инструменталдық программалық жасақтама", "B) Қолданбалы программалық жасақтама", "C) Лицензияланған программалар", "D) Жүйелік программалық жасақтама"], "answer": 1}, {"q": "62. Берілген шарттарда пайдаланушыға ұсынылатын программалық жасақтама қызметтерінің деңгейінің және осы үшін пайдаланылатын ресурстар көлемінің арақатынасы", "options": ["A) Сенімділік", "B) Функционалдық", "C) Тиімділік", "D) Мобильділік"], "answer": 2}, {"q": "63. Программалық жасақтаманың нақты немесе болжалды пайдаланушы қажеттіліктерін қанағаттандыратын функциялар жиынтығын орындау мүмкіндігі", "options": ["A) Сенімділік", "B) Функционалдық", "C) Тиімділік", "D) Мобильділік"], "answer": 1}, {"q": "64. Берілген шарттарда және нақты уақыт кезеңінде белгілі бір функцияларды қалтқысыз орындау мүмкіндігі", "options": ["A) Сенімділік", "B) Функционалдық", "C) Эргономикалық", "D) Мобильділік"], "answer": 0}, {"q": "65. Белгілі бір пайдаланушының оң эмоцияларын туғызуға мүмкіндік беретін программалық жасақтаманың сипаттамалары", "options": ["A) Сенімділік", "B) Функционалдық", "C) Эргономикалық", "D) Мобильділік"], "answer": 2}, {"q": "66. Программалық жасақтама қабілеті бір ортадан екіншісіне, яғни бір аппараттық платформадан басқасына ауыстырылу мүмкіндігі", "options": ["A) Сенімділік", "B) Функционалдық", "C) Эргономикалық", "D) Мобильділік"], "answer": 3}, {"q": "67. Әрбір шешілетін міндеттер типі үшін процессордың, жадтың, бейнекартаның, ақпарат алмасу шинасының, ең аз уақыт үзілісінен аттап өтетін деректерді барынша тез өңдеу мүмкіндігі", "options": ["A) теңгерілмеген конфигурациясы", "B) теңгерілген конфигурациясы", "C) оңтайлы конфигурация", "D) базалық конфигурация"], "answer": 1}]'::jsonb, now() + interval '7 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№10 ТЕОРИУМ: Компьютерлік желілер', '[{"q": "1. Коммуникациялық құрылғыларды (дискілер, файл, принтер) тиімді пайдалану мақсатында бірыңғай деректерді алмасу арнасына біріктіретін компьютерлік желілер тобы", "options": ["A) операциялық жүйе", "B) компьютерлік желі", "C) программалық жасақтама", "D) желілік тораптар"], "answer": 1}, {"q": "2. Шектеулі аймақта (бір бөлмеде, мекемеде, зауытта т.с.с.) орналасқан компьютерлерді біріктіреді", "options": ["A) корпоративтік желі", "B) дүниежүзілік желі", "C) жергілікті желі", "D) мемлекеттік желі"], "answer": 2}, {"q": "3. Бір қала немесе аймақ көлемінде компьютерлердің бір жүйеге бірігуінен пайда болатын желі", "options": ["A) аймақтық желі", "B) дүниежүзілік желі", "C) жергілікті желі", "D) мемлекеттік желі"], "answer": 0}, {"q": "4. Дүниежүзі бойынша компьютерлерді ортақ бір арнаға біріктіру арқылы байланыс жасау желісі", "options": ["A) корпоративтік желі", "B) дүниежүзілік желі", "C) жергілікті желі", "D) мемлекеттік желі"], "answer": 1}, {"q": "5. Мемлекеттік желі", "options": ["A) театр кассасы", "B) ішкі істер органдары", "C) банкоматтар", "D) теміржол кассалары"], "answer": 1}, {"q": "6. Желілер тиістілігіне қарай бөлінуі", "options": ["A) корпоративтік желі", "B) жергілікті желі", "C) сымсыз желі", "D) мемлекеттік желі", "E) дүниежүзілік желі", "F) ведомстволық желі"], "answers": [3, 5]}, {"q": "7. Деректерді тарату ортасына байланысты бөлінуі", "options": ["A) корпоративтік желі", "B) жергілікті желі", "C) сымсыз арналар арқылы", "D) мемлекеттік желі", "E) дүниежүзілік желі", "F) кабельдік арналар арқылы"], "answers": [2, 5]}, {"q": "8. Желілер аумақтық таралуына қарай бөлінуі", "options": ["A) корпоративтік желі", "B) жергілікті желі", "C) сымсыз арналар арқылы", "D) мемлекеттік желі", "E) дүниежүзілік желі", "F) кабельдік арналар арқылы"], "answers": [0, 1, 4]}, {"q": "9. Бір немесе бірнеше сымның бірігуімен өрілген өткізгіштерден тұрады", "options": ["A) Сымсыз арналар", "B) Есулі қосақталған кабель", "C) Коаксиалды кабель", "D) Оптикалық талшық"], "answer": 1}, {"q": "10. Қызметі деректерді тасымалдауда жарықтың таралу жылдамдығына негізделген", "options": ["A) Сымсыз арналар", "B) Есулі қосақталған кабель", "C) Коаксиалды кабель", "D) Оптикалық талшық"], "answer": 3}, {"q": "11. Жергілікті желілерде қолданылатын кабельдің бір түрі", "options": ["A) Сымсыз арналар", "B) Есулі қосақталған кабель", "C) Коаксиалды кабель", "D) Оптикалық талшық"], "answer": 2}, {"q": "12. Негізгі ерекшелігі – сигналдар жоғалмайды, бөтендер рұқсатсыз қосылмайды", "options": ["A) Сымсыз арналар", "B) Есулі қосақталған кабель", "C) Коаксиалды кабель", "D) Оптикалық талшық"], "answer": 3}, {"q": "13. Жергілікті желідегі компьютерлердің бір-бірімен байланысу тәсілі", "options": ["A) Wi-Fi", "B) топология", "C) сымсыз байланыс", "D) кабель"], "answer": 1}, {"q": "14. Бір-біріне тізбектеліп жалғанып, жабық шеңбер құрайтын бірнеше компьютерден тұрады", "options": ["A) Сақина тәріздес желі топологиясы", "B) Шина желі топологиясы", "C) Иерархиялық желі топологиясы", "D) Жұлдыз желі топологиясы"], "answer": 0}, {"q": "15. Желіні бұлай ұйымдастыруда компьютерлер бір-біріне тікелей жалғанбай, желілік бейімдеуішке (адаптер) жалғану арқылы байланысады", "options": ["A) Сақина тәріздес желі топологиясы", "B) Шина желі топологиясы", "C) Иерархиялық желі топологиясы", "D) Жұлдыз желі топологиясы"], "answer": 3}, {"q": "16. Бүгінде ең көп қолданылатын әдіс", "options": ["A) Сақина тәріздес желі топологиясы", "B) Шина желі топологиясы", "C) Иерархиялық желі топологиясы", "D) Жұлдыз желі топологиясы"], "answer": 3}, {"q": "17. Егер жоғарыда танысқан «Жұлдыз» желі топологиясына тағы бір бейімдегіш қосылады", "options": ["A) Сақина тәріздес желі топологиясы", "B) Шина желі топологиясы", "C) Иерархиялық желі топологиясы", "D) Жұлдыз желі топологиясы"], "answer": 2}, {"q": "18. Бір ұйымға және оның аумағындағы аймақтарға 