ers": [1, 3, 4]}, {"q": "100. Желі топологиясын, құрылғылардың құрамын және олардың өзара іс-әрекетінің ережелерін айқындайтын деректерді тасымалдауды іске асыратын құрылым", "options": ["A) желі тораптары", "B) желілік хаттама", "C) желілік адаптер", "D) желі архитектурасы"], "answer": 3}, {"q": "101. Компьютерлік желінің бөлігі ретінде басқа құрылғылармен қосылған құрылғы", "options": ["A) желі тораптары", "B) желілік хаттама", "C) желілік адаптер", "D) желі архитектурасы"], "answer": 0}, {"q": "102. Желі ішінде жұмыс істеу үшін әрбір торап жабдықталған желілік интерфейс тақтасы", "options": ["A) желі тораптары", "B) желілік хаттама", "C) желілік адаптер", "D) желі архитектурасы"], "answer": 2}, {"q": "103. Желілік адаптер өндірушісімен орнатылған және нақ осы адаптерді анықтайтын ұзындығы 6 байт сандық код", "options": ["A) домен", "B) IP адрес", "C) MAC адрес", "D) маска"], "answer": 2}, {"q": "104. Пакеттің жүру маршрутын таңдау процесі", "options": ["A) маршрутизатор", "B) маршрутизация", "C) желілік хаттама", "D) коммутатор"], "answer": 1}, {"q": "105. Желіге қосылған құрылғылар арасында байланыс құруға және олармен деректерді алмасуға мүмкіндік беретін ережелер мен әрекеттер жиынтығы", "options": ["A) желі тораптары", "B) желілік хаттама", "C) желілік адаптер", "D) желі архитектурасы"], "answer": 1}, {"q": "106. В класының маскасы", "options": ["A) 255.0.0.0", "B) 255.255.255.0", "C) 255.255.255.255", "D) 255.255.0.0"], "answer": 3}, {"q": "107. Интернеттің жұмыс істеуіне қатысты ұйымдар", "options": ["A) .net", "B) .edu", "C) .info", "D) .com"], "answer": 0}, {"q": "108. Коммерциялық ұйымдар", "options": ["A) .net", "B) .edu", "C) .info", "D) .com"], "answer": 3}, {"q": "109. ҚР Білім департаментімен танылған жоғары білім беру мекемелері", "options": ["A) .net", "B) .edu", "C) .info", "D) .com"], "answer": 1}, {"q": "110. Ақпараттық ресурстар", "options": ["A) .net", "B) .edu", "C) .info", "D) .com"], "answer": 2}]'::jsonb, now() + interval '8 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№11 ТЕОРИУМ: Ақпараттық қауіпсіздік', '[{"q": "1. Шағын көлемдегі, компьютерге зиян келтіру үшін жазылған арнайы программа", "options": ["A) компьютерлік антивирус", "B) компьютерлік вирус", "C) операциялық жүйе", "D) ақпараттық қауіпсіздік"], "answer": 1}, {"q": "2. Компьютер жадында тұрақты сақталатын вирустар", "options": ["A) резиденттік", "B) резиденттік емес", "C) зиянды", "D) зиянсыз"], "answer": 0}, {"q": "3. Компьютер жадында тұрақты сақталмайтын вирустар", "options": ["A) резиденттік", "B) резиденттік емес", "C) зиянды", "D) зиянсыз"], "answer": 1}, {"q": "4. Көлемді программаларды түзету кезінде белсенділік көрсетіп, программаға жабысатын, түрлі зиянды әрекеттерді орындайтын вирус", "options": ["A) вирус-қақпан", "B) логикалық бомбалар", "C) құрттар", "D) троян аттары"], "answer": 0}, {"q": "5. Қарапайым программаларға кіріп, жасырынып жататын, тек белгілі бір шарттар орындалғанда ғана әсер ете бастайтын вирус", "options": ["A) вирус-қақпан", "B) логикалық бомбалар", "C) құрттар", "D) троян аттары"], "answer": 1}, {"q": "6. Жасалу құрылымы мен көбею жолы оңай болғандықтан, көбіне компьютер желілерін толық жаулап алатын вирус", "options": ["A) вирус-қақпан", "B) логикалық бомбалар", "C) құрттар", "D) троян аттары"], "answer": 3}, {"q": "7. Жүйелік программалаушылардың ақпараттық есептеу желілерінің бос тұрған ресурстарын анықтау программасына кіріп, бос құрылғыларды тектен-тек жұмыс істеуге мәжбүр ететін вирус", "options": ["A) вирус-қақпан", "B) логикалық бомбалар", "C) құрттар", "D) троян аттары"], "answer": 2}, {"q": "8. Желі бойынша көшірмелерін таратуға арналған программа", "options": ["A) тыңшы программалар", "B) құрттар", "C) трояндық программалар", "D) вирус"], "answer": 1}, {"q": "9. Компьютерді пайдаланушы туралы оның рұқсатынсыз ақпарат жинайтын программалық жабдықтама", "options": ["A) тыңшы программалар", "B) құрттар", "C) трояндық программалар", "D) вирус"], "answer": 0}, {"q": "10. Пайдаланушының санкцияланбаған әрекеті кезінде орындалатын зиянды программа", "options": ["A) тыңшы программалар", "B) құрттар", "C) трояндық программалар", "D) вирус"], "answer": 2}, {"q": "11. Мемлекеттік ақпараттық ресурстардың, сондай-ақ ақпарат саласында жеке адамның құқықтары мен қоғам мүдделері қорғалуының жай-күйін сипаттайды", "options": ["A) ақпартты қорғау", "B) алаяқтық", "C) ақпараттық қауіпсіздік", "D) вирус"], "answer": 2}, {"q": "12. Ақпаратты ұрлау, жоғалту, рұқсатсыз жою, өзгерту, маңызына тимей түрлендіру, рұқсатсыз көшірмесін жасау мен бұғаттаудың алдын алу үшін жүргізілетін шаралар кешені", "options": ["A) ақпартты қорғау", "B) алаяқтық", "C) ақпараттық қауіпсіздік", "D) вирус"], "answer": 0}, {"q": "13. Ақпараттық қауіпсіздіктің маңызды 3 жайы", "options": ["A) сенімділік", "B) құпиялылық", "C) тұтастық", "D) дәлдік", "E) қолжетімділік", "F) қауіпсіздік"], "answers": [1, 2, 4]}, {"q": "14. Санаулы уақыт ішінде керекті ақпараттық қызмет алуға болатын мүмкіндік", "options": ["A) сенімділік", "B) құпиялылық", "C) тұтастық", "D) қолжетімділік"], "answer": 3}, {"q": "15. Ақпараттың бұрмаланудан және заңсыз өзгертуден қорғалуы", "options": ["A) сенімділік", "B) құпиялылық", "C) тұтастық", "D) қолжетімділік"], "answer": 2}, {"q": "16. Ақпараттың, техникалық құралдар мен өңдеу технологияларының ақпаратқа кедергісіз (бөгетсіз) қол жеткізу қабілетімен сипатталатын қасиеті", "options": ["A) сенімділік", "B) құпиялылық", "C) тұтастық", "D) қолжетімділік"], "answer": 3}, {"q": "17. Заңсыз қол жеткізуден немесе оқудан қорғау", "options": ["A) сенімділік", "B) құпиялылық", "C) тұтастық", "D) қолжетімділік"], "answer": 1}, {"q": "18. Компьютердегі деректер, яғни компьютерде сақталатын, өңделетін, автономды жүйе ретінде қарастырылатын барлық дерек мәселесі", "options": ["A) компьютерлік вирус", "B) компьютерлік қауіпсіздік", "C) желілік қауіпсіздік", "D) компьютерлік желілер"], "answer": 1}, {"q": "19. Желілік құрылғылар арасында ақпарат алмасу кезіндегі қорғау және рұқсатсыз кіруден қорғау мәселелері", "options": ["A) компьютерлік вирус", "B) компьютерлік қауіпсіздік", "C) желілік қауіпсіздік", "D) компьютерлік желілер"], "answer": 2}, {"q": "20. Желілік құрылғылар арасында ақпарат алмасу кезіндегі қорғау мен рұқсатсыз кіруден қорғау", "options": ["A) компьютерлік вирус", "B) компьютерлік қауіпсіздік", "C) желілік қауіпсіздік", "D) компьютерлік желілер"], "answer": 2}, {"q": "21. Бүкіл әлем бойынша орналасқан зақымдалған құрылғылардың желісі", "options": ["A) зиянды программалар", "B) DoS-шабуыл", "C) ботнет", "D) DDoS-шабуыл"], "answer": 2}, {"q": "22. Компьютерге, серверге немесе компьютерлік желіге зиян келтіреді", "options": ["A) зиянды программалар", "B) DoS-шабуыл", "C) ботнет", "D) DDoS-шабуыл"], "answer": 0}, {"q": "23. Компьютерді істен шығарады, бірақ ақпарат ұрламайды, басқа пайдаланушылар құрбан болған компьютерге қол жеткізе алмай, компьютердің барлық ресурстарына ие болады", "options": ["A) зиянды программалар", "B) DoS-шабуыл", "C) ботнет", "D) DDoS-шабуыл"], "answer": 1}, {"q": "24. Бірнеше компьютерден бір уақытта жасалған шабуыл", "options": ["A) зиянды программалар", "B) DoS-шабуыл", "C) ботнет", "D) DDoS-шабуыл"], "answer": 3}, {"q": "25. Құпия ақпаратты алаяқтық жолмен алуға бағытталған әдіс", "options": ["A) фишинг", "B) кибербуллинг", "C) претекстинг", "D) троллинг"], "answer": 0}, {"q": "26. Желі қолданушысына зәбір көрсету, агрессия, қорқыту мазмұнындағы хабарламалар жіберу", "options": ["A) фишинг", "B) кибербуллинг", "C) претекстинг", "D) троллинг"], "answer": 1}, {"q": "27. Алдын ала жасалған сценарий бойынша жасалған әрекет", "options": ["A) фишинг", "B) кибербуллинг", "C) претекстинг", "D) троллинг"], "answer": 2}, {"q": "28. Адам ақылымен жасалған өнертабыс", "options": ["A) авторлық құқық", "B) интеллектуалды жекеменшік", "C) цифрлық бедел", "D) зиянды программа"], "answer": 1}, {"q": "29. Ғылым, өнер, әдебиет саласындағы туындыларға деген интеллектуалды жекеменшік құқығы", "options": ["A) авторлық құқық", "B) интеллектуалды жекеменшік", "C) цифрлық бедел", "D) зиянды программа"], "answer": 0}, {"q": "30. Пайдаланушы туралы желідегі жағымды немесе жағымсыз мәліметтер", "options": ["A) авторлық құқық", "B) интеллектуалды жекеменшік", "C) цифрлық бедел", "D) зиянды программа"], "answer": 2}, {"q": "31. Бірнеше боттар мен хостардан тұратын компьютерлік жүйе", "options": ["A) ботнет", "B) бот", "C) брандмауэр", "D) вирус"], "answer": 0}, {"q": "32. Вирустардан, брандмауэрлардан, компьютерді қашықтан басқару программаларынан, операциялық жүйені қорғау құралдарынан тұратын компьютерлік желі", "options": ["A) ботнет", "B) бот", "C) брандмауэр", "D) вирус"], "answer": 1}, {"q": "33. Желілік пакеттер мен қолданылатын программаларды қадағалайтын аппараттық-программалық комплекс", "options": ["A) ботнет", "B) бот", "C) брандмауэр", "D) вирус"], "answer": 2}, {"q": "34. Веб-қызметтер мен басқа компьютерлерді істен шығару үшін қолданылатын шабуылдар", "options": ["A) DDoS-шабуыл", "B) DoS-шабуыл", "C) аккаунт", "D) спам"], "answer": 1}, {"q": "35. Виртуалды қарым-қатынас тәсілі", "options": ["A) кибербуллинг", "B) фишинг", "C) троллинг", "D) спам"], "answer": 2}, {"q": "36. Желілік алаяқтық", "options": ["A) кибербуллинг", "B) фишинг", "C) троллинг", "D) спам"], "answer": 1}, {"q": "37. Қажет емес жарнамалық ақпаратты тарату", "options": ["A) кибербуллинг", "B) фишинг", "C) троллинг", "D) спам"], "answer": 3}, {"q": "38. Электрондық коммуникация құралдарының көмегімен азапқа салу, қорлау немесе қоқан-лоқы жасау", "options": ["A) кибербуллинг", "B) фишинг", "C) троллинг", "D) спам"], "answer": 0}, {"q": "39. Көп пайдаланылатын онлайн-ойындарда басқа ойыншыларды қудалау", "options": ["A) флейминг", "B) грифинг", "C) хейтинг", "D) хейт-спич"], "answer": 1}, {"q": "40. Нақты бір адамға немесе нәрсеге, адамдар тобына жақтырмайтындығы туралы жалпылама айтып жеткізу", "options": ["A) флейминг", "B) грифинг", "C) хейтинг", "D) хейт-спич"], "answer": 3}, {"q": "41. Нақты бір адамға немесе нәрсеге бағытталған жағымсыз комментарийлер арқылы зиян келтіру", "options": ["A) флейминг", "B) грифинг", "C) хейтинг", "D) хейт-спич"], "answer": 2}, {"q": "42. Чаттағы еш мағынасы жоқ сөзталастар", "options": ["A) флейминг", "B) грифинг", "C) хейтинг", "D) хейт-спич"], "answer": 0}, {"q": "43. Белгілі бір тұлғалар немесе олардың атынан әрекет жасайтын үрдістер ғана ақпаратты оқу, жазу, құрастыру және жою құқығына ие бола алатындай етіп құрылған жүйе", "options": ["A) сенімді жүйе", "B) қауіпсіз жүйе", "C) жүйенің сенімділігі", "D) қауіпсіздік саясаты"], "answer": 1}, {"q": "44. Әртүрлі құпия ақпаратты қатынас құру құқығын бұзбай пайдаланушылар тобының бір уақытта өңдеуін қамтамасыз ету үшін жеткілікті ақпараттық және программалық құралдарды қолданатын жүйе", "options": ["A) сенімді жүйе", "B) қауіпсіз жүйе", "C) жүйенің сенімділігі", "D) қауіпсіздік саясаты"], "answer": 0}, {"q": "45. Ақпаратты қалайша өңдейтінін, қорғайтынын және тарататынын анықтайтын заңдар, ережелер және тәртіп нормаларының жиыны", "options": ["A) кепілдік", "B) қауіпсіз жүйе", "C) жүйенің сенімділігі", "D) қауіпсіздік саясаты"], "answer": 3}, {"q": "46. Жүйенің сәулетіне және жүзеге асырылуына көрсетілетін сенім өлшемі", "options": ["A) кепілдік", "B) қауіпсіз жүйе", "C) жүйенің сенімділігі", "D) қауіпсіздік саясаты"], "answer": 0}, {"q": "47. Басқа бөгде адамдардың (қарсыластың) хабарламаны ұрлауынан, өшіруінен, көруінен және т.б. өзгертулерден қорғау үшін хабарламаның түрленуін қарастырады", "options": ["A) криптоанализ", "B) криптография", "C) криптология", "D) криптограф"], "answer": 1}, {"q": "48. Хабарды құпиялылығын нақтылылығын сақталатын әдістермен қамтамасыз етеді", "options": ["A) криптоанализ", "B) криптография", "C) криптология", "D) криптограф"], "answer": 3}, {"q": "49. Криптологияның екі бөлімі", "options": ["A) криптоанализ", "B) криптография", "C) криптоаналитика", "D) криптограф", "E) криптограмма", "F) криптожүйе"], "answers": [0, 1]}, {"q": "50. Ақпаратты кілтсіз кері шифрлау мәселесімен айналысады", "options": ["A) криптоанализ", "B) криптография", "C) криптоаналитика", "D) криптограф"], "answer": 0}, {"q": "51. Шифрланған хабарды немесе кілтті, не екеуін де оқуға мүмкіндік беретін криптожүйенің осал жерлерін іздеумен шұғылданады", "options": ["A) криптоанализ", "B) криптография", "C) криптоаналитика", "D) криптограф"], "answer": 2}, {"q": "52. Криптографтың ашық мәтінге қолданған амалынан кейінгі нәтижесі", "options": ["A) криптоанализ", "B) криптография", "C) криптожүйе", "D) криптограмма"], "answer": 3}, {"q": "53. Шифрлау алгоритмі, сондай-ақ алуан түрлі кілттердің, ашық және шифрланған мәтіндердің жиынтығы", "options": ["A) криптоанализ", "B) криптография", "C) криптожүйе", "D) криптограмма"], "answer": 2}, {"q": "54. Шифр арқылы ашық мәтіннің шифрлы мәтінге айналу процесі", "options": ["A) шифрлау", "B) криптоанализ", "C) криптожүйе", "D) криптограмма"], "answer": 0}, {"q": "55. Пайдаланушы немесе нысанға оны тану үшін өзіне ғана тән атау немесе бейне беру", "options": ["A) идентификациялау", "B) идентификация", "C) аутентификация", "D) идентификатор"], "answer": 1}, {"q": "56. Пайдаланушыны идентификаторы бойынша анықтау рәсімі", "options": ["A) идентификациялау", "B) идентификация", "C) аутентификация", "D) идентификатор"], "answer": 0}, {"q": "57. Компьютерлік жүйеде тіркелген әрбір пайдаланушыны анықтайтын белгілі бір ақпарат", "options": ["A) идентификациялау", "B) идентификация", "C) аутентификация", "D) идентификатор"], "answer": 3}, {"q": "58. Пайдаланушының немесе құрылғының шын екендігін тексеру", "options": ["A) идентификациялау", "B) идентификация", "C) аутентификация", "D) идентификатор"], "answer": 2}, {"q": "59. Идентификациялау процесінің әдістері", "options": ["A) статикалық", "B) динамикалық", "C) тұрақты", "D) атрибутивтік", "E) тұрақсыз", "F) биометриялық"], "answers": [3, 5]}, {"q": "60. Биометрлік аутентификация жіктелуі", "options": ["A) статикалық", "B) динамикалық", "C) тұрақты", "D) атрибутивтік", "E) тұрақсыз", "F) идентификациялық"], "answers": [0, 1]}, {"q": "61. Биометрлік аутентификацияның статикалық әдіс сипаттамалары", "options": ["A) көз торы", "B) қолжазба", "C) дауыс", "D) ДНҚ", "E) бет пішіні", "F) пернетақталық қолжазба"], "answers": [0, 3, 4]}, {"q": "62. Биометрлік аутентификацияның динамикалық әдіс сипаттамалары", "options": ["A) саусақ іздері", "B) қолжазба", "C) дауыс", "D) ДНҚ", "E) бет пішіні", "F) пернетақталық қолжазба"], "answers": [1, 2, 5]}, {"q": "63. Ақпарат құпиялылығы", "options": ["A) статикалық", "B) заңсыз", "C) қызметтік", "D) динамикалық", "E) заңды", "F) пәндік"], "answers": [2, 5]}, {"q": "64. Кез келген қорғау жүйесінің ең әлсіз тұсы", "options": ["A) компьютер", "B) адам", "C) вирус", "D) заң"], "answer": 1}, {"q": "65. Байланыс арналарын оларға қолжетімдік барынша қиын болатындай етіп тарату мен ұйымның қауіпсіздік саясаты", "options": ["A) ұйымдастырушылық шаралары", "B) техникалық шаралары", "C) программалық шаралары", "D) сервистік шаралары"], "answer": 0}, {"q": "66. Белгілі бір деректердің қолжетімдігіне пароль орнату, мәтінді шифрлау, файлдарды уақытша жою мен қауіпті программалардан қорғауды қамтамасыз ету", "options": ["A) ұйымдастырушылық шаралары", "B) техникалық шаралары", "C) программалық шаралары", "D) сервистік шаралары"], "answer": 2}, {"q": "67. Бейнебақылау мен дабыл жүйелері, ақпараттың таралуы мүмкін барлық жолдарды бұғаттап, алдын алатын басқа да құралдар", "options": ["A) ұйымдастырушылық шаралары", "B) техникалық шаралары", "C) программалық шаралары", "D) сервистік шаралары"], "answer": 1}, {"q": "68. Шифрлау алгоритмінің параметрі", "options": ["A) беріктік", "B) криптография", "C) кілт", "D) криптоанализ"], "answer": 2}, {"q": "69. Криптографиялық алгоритмнің шифрдан ашуды болдырмауы", "options": ["A) шифрдың криптоберіктігі", "B) алгоритм беріктігі", "C) кілт", "D) криптоанализ"], "answer": 0}, {"q": "70. Шифрдан ашуда өте көп көлемді есептеулерді талап ететін алгоритм", "options": ["A) шифрдың криптоберіктігі", "B) алгоритм беріктігі", "C) кілт", "D) криптоанализ"], "answer": 1}, {"q": "71. Қорғау жүйелерінің ішіндегі ең қуаттыларының бірі", "options": ["A) пароль арқылы қорғау", "B) арнайы заттарды қолдану", "C) биометриялық тексеру", "D) құпия ақпаратты қолдану"], "answer": 2}, {"q": "72. Парольдің екі түрі", "options": ["A) қызметтік", "B) пәндік", "C) динамикалық", "D) атрибутивтік", "E) тұрақты", "F) сыртқы"], "answers": [2, 4]}, {"q": "73. Ақпаратты қорғау әдістері", "options": ["A) ұйымдастырушылық", "B) статикалық", "C) симметриялық", "D) құқықтық", "E) инженерлік-техникалық", "F) асимметриялық"], "answers": [0, 3, 4]}, {"q": "74. Шифрлау алгоримтдері", "options": ["A) ұйымдастырушылық", "B) статикалық", "C) симметриялық", "D) құқықтық", "E) инженерлік-техникалық", "F) асимметриялық"], "answers": [2, 5]}, {"q": "75. Шифрлеу стандарты ретінде қабылданған блоктық шифрлау алгоритмі", "options": ["A) DES", "B) AES", "C) RSA", "D) ADL"], "answer": 1}, {"q": "76. Шифрлеуге де, әрі цифрлық қолтаңбаларға да сай келетін бірінші жүйе", "options": ["A) DES", "B) AES", "C) RSA", "D) ADL"], "answer": 2}, {"q": "77. Биометрикалық физиологиялық әдістер", "options": ["A) бетті тану", "B) жазу мәнерін талдау", "C) саусақ іздерін алу", "D) қол саусақтарының геометриясы", "E) клавиатура жазу мәнерін талдау", "F) дауыс тембрін талдау"], "answers": [0, 2, 3]}, {"q": "78. Биометрикалық мінез-құлық әдістер", "options": ["A) бетті тану", "B) жазу мәнерін талдау", "C) саусақ іздерін алу", "D) қол саусақтарының геометриясы", "E) клавиатура жазу мәнерін талдау", "F) дауыс тембрін талдау"], "answers": [1, 4, 5]}]'::jsonb, now() + interval '9 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№12 ТЕОРИУМ: Цифрлық сауаттылық. 3D модельдеу. Аппараттық қамтамасыз ету', '[{"q": "1. Интеллектуалдық меншікке қатысты құқықтық қатынастарды реттейтін азаматтық құқық саласы", "options": ["A) авторлық құқық", "B) желілік қауіпсіздік", "C) компьютерлік қауіпсіздік", "D) цифрландыру"], "answer": 0}, {"q": "2. Электрондық құжаттың дұрыстығын, оның тиесілілігін әрі мазмұнының өзгермейтіндігін растайтын электрондық цифрлық символдар жиынтығы", "options": ["A) цифрлық сертификат", "B) электрондық цифрлық қолтаңба", "C) ашық кілт", "D) жабық кілт"], "answer": 1}, {"q": "3. Басты мақсат - азаматтарға қызмет көрсетудің барынша жеделдігі", "options": ["A) транзакциялық кезең", "B) ақпаратттық кезең", "C) трансформациялық кезең", "D) интербелсенді кезең"], "answer": 2}, {"q": "4. Қазақстан экономикасын дамыту қарқынын жеделдетуге және азаматтардың тұрмыс сапасын жақсартуға арналған үдеріс", "options": ["A) Қазақстандағы құқықтық қорғау", "B) Қазақстандағы цифрландыру", "C) Қазақстандағы қауіпсіздік жүйесі", "D) Қазақстандағы экономика"], "answer": 1}, {"q": "5. Халық бен бизнестің сұранысын алдын ала болжай отырып, қызметтер көрсету үшін мемлекеттің инфрақұрылымын қайта құру", "options": ["A) цифрлық мемлекетке өту", "B) адами капиталды дамыту", "C) экономика салаларын цифрландыру", "D) инновациялық экожүйені құру"], "answer": 0}, {"q": "6. Бизнес, ғылым саласы және мемлекет арасында берік байланысы бар технологиялық кәсіпкерлікті дамыту, сондай-ақ инновацияларды енгізу үшін жағдай жасау", "options": ["A) цифрлық мемлекетке өту", "B) адами капиталды дамыту", "C) экономика салаларын цифрландыру", "D) инновациялық экожүйені құру"], "answer": 3}, {"q": "7. Креативтік қоғам құруды және жаңа нақтылықтар – білімдер экономикасына өтуді қамтитын түрлендірулер", "options": ["A) цифрлық мемлекетке өту", "B) адами капиталды дамыту", "C) экономика салаларын цифрландыру", "D) цифрлық Жібек жолын іске асыру"], "answer": 1}, {"q": "8. Озық технологиялар және мүмкіндіктерді пайдалана отырып, капиталдандырудың өсуі мен еңбек өтімділігін арттыратын ҚР экономикасының әртүрлі салаларын қайта құру", "options": ["A) цифрлық мемлекетке өту", "B) адами капиталды дамыту", "C) экономика салаларын цифрландыру", "D) цифрлық Жібек жолын іске асыру"], "answer": 2}, {"q": "9. Деректерді беру, сақтау және өңдеудің жоғары жылдамдықтағы және қорғалған инфрақұрылымын бүкіл аумақта дамыту", "options": ["A) цифрлық мемлекетке өту", "B) адами капиталды дамыту", "C) экономика салаларын цифрландыру", "D) цифрлық Жібек жолын іске асыру"], "answer": 3}, {"q": "10. Өз атына тіркеу куәлігі берілген, тіркеу куәлігінде көрсетілген ашық кілтке сәйкес келетін жабық кілтті заңды түрде иеленетін жеке немесе заңды тұлға", "options": ["A) тіркеу куәлігінің иесі", "B) электронды құжат", "C) ЭЦҚ", "D) электронды цифрлық қолтаңба құралдары"], "answer": 0}, {"q": "11. Ақпарат электронды-цифрлық нысанда ұсынылған және электронды цифрлық қолтаңба арқылы куәландырылған құжат", "options": ["A) тіркеу куәлігінің иесі", "B) электронды құжат", "C) ЭЦҚ", "D) электронды цифрлық қолтаңба құралдары"], "answer": 1}, {"q": "12. ЭЦҚ құру және оның түпнұсқалығын тексеру үшін пайдаланылатын программалық және техникалық құралдардың жиынтығы", "options": ["A) тіркеу куәлігінің иесі", "B) электронды құжат", "C) ЭЦҚ", "D) электронды цифрлық қолтаңба құралдары"], "answer": 3}, {"q": "13. Кез келген тұлғаның қолы жететін және электронды құжаттағы электронды цифрлық қолтаңбаның түпнұсқалығын растауға арналған электронды цифрлық нышандар дәйектілігі", "options": ["A) тіркеу куәлігінің иесі", "B) электронды құжат", "C) электронды цифрлық қолтаңбаның ашық кілті", "D) электронды цифрлық қолтаңбаның жабық кілті"], "answer": 2}, {"q": "14. Тіркеу куәлігінің иесіне белгілі және электронды цифрлық қолтаңба құралдарын пайдалана отырып, электронды цифрлық қолтаңбаны жасауға арналған электронды цифрлық нышандар дәйектілігі", "options": ["A) тіркеу куәлігінің иесі", "B) электронды құжат", "C) электронды цифрлық қолтаңбаның ашық кілті", "D) электронды цифрлық қолтаңбаның жабық кілті"], "answer": 3}, {"q": "15. Сертификаттау орталығына тиесілі сертификат, оның көмегімен орталық берген басқа да сертификаттардың шынайылығы тексеріледі", "options": ["A) түбірлік сертификат", "B) электронды құжат", "C) электронды цифрлық қолтаңбаның ашық кілті", "D) электронды цифрлық қолтаңбаның жабық кілті"], "answer": 0}, {"q": "16. Күнделікті және кәсіби қызметтерде цифрлық технологияларды және интернет ресурстарын тиімді және қауіпсіз пайдалана білу біліктілігі", "options": ["A) цифрлық сауаттылық", "B) компьютерлік сауаттылық", "C) цифрлық қолтаңба", "D) компьютерлік қолтаңба"], "answer": 0}, {"q": "17. Практикалық жұмыстарда компьютерді және негізгі қолданбалы программаларды қолдану біліктілігі мен дағдысы", "options": ["A) цифрлық сауаттылық", "B) компьютерлік сауаттылық", "C) цифрлық қолтаңба", "D) компьютерлік қолтаңба"], "answer": 1}, {"q": "18. Оңтайландырылған кешенді мемлекеттік қызметтер", "options": ["A) интеграциялық кезең", "B) ақпараттық кезең", "C) транзакциялық кезең", "D) интербелсенді кезең"], "answer": 0}, {"q": "19. Анықтама алу, электрондық формаларды беру мүмкіндігі", "options": ["A) интеграциялық кезең", "B) ақпараттық кезең", "C) транзакциялық кезең", "D) интербелсенді кезең"], "answer": 3}, {"q": "20. Төлемдерді жүзеге асыру мүмкіндігі", "options": ["A) интеграциялық кезең", "B) ақпараттық кезең", "C) транзакциялық кезең", "D) интербелсенді кезең"], "answer": 2}, {"q": "21. Мемлекеттік органдардың web-сайттары статистикалық ақпаратты ұсынады", "options": ["A) интеграциялық кезең", "B) ақпараттық кезең", "C) транзакциялық кезең", "D) интербелсенді кезең"], "answer": 1}, {"q": "22. Шынайылықтың компьютерлік моделі немесе қандай да бір жағдайды қалпына келтіру", "options": ["A) кеңейтілген шынайылық", "B) виртуалды шынайылық", "C) аралас шынайылық", "D) толық шынайылық"], "answer": 1}, {"q": "23. Бар шынайылыққа компьютермен модельденген жақсарту қабаттарын салатын технология", "options": ["A) кеңейтілген шынайылық", "B) виртуалды шынайылық", "C) аралас шынайылық", "D) толық шынайылық"], "answer": 0}, {"q": "24. Нақты әлемнің физикалық элементтерімен толықтырылған виртуалды әлем", "options": ["A) кеңейтілген шынайылық", "B) виртуалды шынайылық", "C) кеңейтілген виртуалдылық", "D) толық шынайылық"], "answer": 2}, {"q": "25. Виртуалды элементтері бар нақты әлем", "options": ["A) кеңейтілген шынайылық", "B) виртуалды шынайылық", "C) кеңейтілген виртуалдылық", "D) толық шынайылық"], "answer": 0}, {"q": "26. Бізді қоршаған ортаның бәрі", "options": ["A) кеңейтілген шынайылық", "B) виртуалды шынайылық", "C) кеңейтілген виртуалдылық", "D) толық шынайылық"], "answer": 3}, {"q": "27. Цифрлық әлем", "options": ["A) кеңейтілген шынайылық", "B) виртуалды шынайылық", "C) кеңейтілген виртуалдылық", "D) толық шынайылық"], "answer": 1}, {"q": "28. Виртуалды және кеңейтілген шынайылықтың кемшіліктері", "options": ["A) құрылғылар құнының арзандығы", "B) қауіпсіздік", "C) қолжетімділік", "D) программалық қамтамасыз ету", "E) аппараттық қамтамасыз ету", "F) сапалы контенттің көптігі"], "answers": [1, 3, 4]}, {"q": "29. Шолу жасау ауқымы үлкен фотосурет", "options": ["A) панорамалы фотосурет", "B) сфералық панорама", "C) виртуалды тур", "D) 3D панорама"], "answer": 0}, {"q": "30. Сфераға немесе кубқа проекцияланған панорамалы фотосурет", "options": ["A) панорамалы фотосурет", "B) сфералық панорама", "C) виртуалды тур", "D) 3D панорама"], "answer": 3}, {"q": "31. Бірнеше панорамалық фотосуреттің жиынтығы", "options": ["A) панорамалы фотосурет", "B) хотспоттар", "C) виртуалды тур", "D) 3D панорама"], "answer": 2}, {"q": "32. Панораманың белгілі бір жерінде көрсетілген әрі онымен бірге айналатын фотосуреттер", "options": ["A) панорамалы фотосурет", "B) хотспоттар", "C) виртуалды тур", "D) 3D панорама"], "answer": 1}, {"q": "33. Компьютерге басқа компьютерді оған орнатылған параметрлерімен эмуляциялайтын программалық қамтамасыз ету", "options": ["A) виртуалды шынайылық", "B) виртуалды тур", "C) виртуалды мәшине", "D) виртуалды операциялық жүйе"], "answer": 2}, {"q": "34. Виртуалды мәшинеге орнатылған операциялық жүйе", "options": ["A) виртуалды шынайылық", "B) виртуалды тур", "C) виртуалды мәшине", "D) виртуалды операциялық жүйе"], "answer": 3}, {"q": "35. Виртуалдау платформасы", "options": ["A) виртуалды шынайылық", "B) гипервизор", "C) виртуалды мәшине", "D) виртуалды операциялық жүйе"], "answer": 1}, {"q": "36. Тікелей негізгі аппараттық қамтамасыз етуде іске қосып, оны өз бетінше басқарады", "options": ["A) 1-типті гипервизор", "B) 2-типті гипервизор", "C) монолитті гипервизор", "D) микроядролы гипервизор"], "answer": 0}, {"q": "37. Аппараттық құрылғы драйверлерін өз кодтарына енгізетін архитектура", "options": ["A) 1-типті гипервизор", "B) 2-типті гипервизор", "C) монолитті гипервизор", "D) микроядролы гипервизор"], "answer": 2}, {"q": "38. Виртуалды мәшиненің артықшылығы", "options": ["A) беріктік", "B) сенімділік", "C) инкапсуляция", "D) қауіпсіздік", "E) оқшаулау", "F) бөлу"], "answers": [2, 4, 5]}, {"q": "39. Пайдаланушыға виртуалды үшөлшемді кеңістіктің ортасында болуға мүмкіндік береді", "options": ["A) 3D жобалы VR", "B) қарапайым VR", "C) бірнеше қолданушы VR-і", "D) маркерлер негізінде VR"], "answer": 1}, {"q": "40. Пайдаланушыға виртуалды шындық арқылы объектілермен өзара әрекеттесуге мүмкіндік береді", "options": ["A) 3D жобалы VR", "B) қарапайым VR", "C) бірнеше қолданушы VR-і", "D) маркерлер негізінде VR"], "answer": 0}, {"q": "41. Жоғары деңгейдегі графика, анимация, 3D жобалау, яғни озық функцияларды біріктірген орта", "options": ["A) 3D жобалы VR", "B) қарапайым VR", "C) бірнеше қолданушы VR-і", "D) маркерлер негізінде VR"], "answer": 2}, {"q": "42. Белгілі бір виртуалды объектіні таниды және сол объект туралы керекті ақпараттарды береді", "options": ["A) маркерлер негізінде кеңейтілген шындық", "B) позициялық кеңейтілген шындық", "C) проекциялар негізінде кеңейтілген шындық", "D) суперпозиция негізінде кеңейтілген шындық"], "answer": 0}, {"q": "43. Нақты уақыт режимінде қосымша элементтермен толықтыру, объектілерді тану", "options": ["A) маркерлер негізінде кеңейтілген шындық", "B) позициялық кеңейтілген шындық", "C) проекциялар негізінде кеңейтілген шындық", "D) суперпозиция негізінде кеңейтілген шындық"], "answer": 3}, {"q": "44. Орналасқан жерге байланысты виртуалды суреттер мен жол сілтемелер пайда болады", "options": ["A) маркерлер негізінде кеңейтілген шындық", "B) позициялық кеңейтілген шындық", "C) проекциялар негізінде кеңейтілген шындық", "D) суперпозиция негізінде кеңейтілген шындық"], "answer": 1}, {"q": "45. Экран бетіндегі 3D үлгідегі сурет адаммен өзара әрекеттесе алады", "options": ["A) маркерлер негізінде кеңейтілген шындық", "B) позициялық кеңейтілген шындық", "C) проекциялар негізінде кеңейтілген шындық", "D) суперпозиция негізінде кеңейтілген шындық"], "answer": 2}, {"q": "46. Жеке үдерісті қолдау мақсатына бағытталып, оны орындауға арналған", "options": ["A) үдерістік виртуалды машина", "B) жүйелік виртуалды машина", "C) ішкі виртуалды машина", "D) сыртқы виртуалды машина"], "answer": 0}, {"q": "47. Толық қызметті, тұрақты әрекет ететін жүйелік орта", "options": ["A) үдерістік виртуалды машина", "B) жүйелік виртуалды машина", "C) ішкі виртуалды машина", "D) сыртқы виртуалды машина"], "answer": 1}, {"q": "48. Ең маңызды ерекшелігі көлемі мен тасымалдану қабілеті және көптеген функционалдық мүмкіндіктері бар құрылғылар", "options": ["A) планшеттер", "B) электронды кітаптар", "C) ноутбук", "D) смартфондар"], "answer": 3}, {"q": "49. Мобильді құрылғының негізгі (бастапқы) қуат көзі", "options": ["A) аккумуляторлық батарея", "B) қоректендіру контроллері", "C) жүйелік тақша", "D) орталық процессор"], "answer": 0}, {"q": "50. Мобильді GSM сигналын қабылдау және беру құрылғысы", "options": ["A) сенсорлық экран", "B) қабылдағыш-таратқыш", "C) антенна", "D) жедел жады"], "answer": 1}, {"q": "51. Базалық станция шығаратын энергияны жинақтауға және оны кейіннен қабылдау жолы тізбегіне беруге арналған құрылғы", "options": ["A) сенсорлық экран", "B) қабылдағыш-таратқыш", "C) антенна", "D) жедел жады"], "answer": 2}, {"q": "52. Деректерді енгізу және мобильді құрылғыларды басқару үшін қызмет етеді", "options": ["A) сенсорлық экран", "B) қабылдағыш-таратқыш", "C) антенна", "D) жедел жады"], "answer": 0}, {"q": "53. Адамның сезімдеріне әсер етіп, виртуалды ортамен өзара әрекеттесуін имитациялайтын техникалық құралдармен жасалған әлем", "options": ["A) виртуалды шынайылық", "B) кеңейтілген шынайылық", "C) аралас шынайылық", "D) компьютерлік модель"], "answer": 0}, {"q": "54. Көру бейнелерінің бірлескен сипатын сәйкестендіріңіз", "left": ["монокулярлы көру", "бинокулярлы көру"], "options": ["A) бір көзбен көру, 140°", "B) екі көзбен көру, 360°", "C) бір көзбен көру, 180°", "D) екі көзбен көру, 180°"], "pairs": [0, 3]}, {"q": "55. Оптикалық сәулелердің қиылысында орналасқан объектив осіндегі нүкте", "options": ["A) сфералық нүкте", "B) нодалды нүкте", "C) деңгейлік нүкте", "D) фотонүкте"], "answer": 1}, {"q": "56. Белгілі бір суреті немесе фотосуреті бар терезені шығаратын хот-спот", "options": ["A) сфералық нүкте", "B) нодалды нүкте", "C) деңгейлік нүкте", "D) фотонүкте"], "answer": 3}, {"q": "57. Unix ядросы негізіндегі операциялық жүйе, тегін, ашық бастапқы коды бар", "options": ["A) Android", "B) iOS", "C) Nokia", "D) Linux"], "answer": 0}, {"q": "58. Unix операциялық жүйесіне ұқсас, тек Apple құрылғыларына арналған операциялық жүйес", "options": ["A) Android", "B) iOS", "C) Nokia", "D) Linux"], "answer": 1}]'::jsonb, now() + interval '10 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№13 ТЕОРИУМ: Жасанды интеллект', '[{"q": "1. Компьютердің немесе роботтың адамдарға тән интеллектуалдық процестерге байланысты тапсырмаларды орындау мүмкіндігі", "options": ["A) жасанды интеллект", "B) машиналық оқыту", "C) виртуалды машина", "D) нейрондық желі"], "answer": 0}, {"q": "2. Адамзат интеллектісінің процесін компьютерлік жүйелер арқылы модельдеу", "options": ["A) жасанды интеллект", "B) машиналық оқыту", "C) виртуалды машина", "D) нейрондық желі"], "answer": 0}, {"q": "3. Білім базасы ретінде компьютерлік жадқа енгізу үшін, білімді формалдау әдістерін әзірлеу", "options": ["A) интеллектті модельдеу", "B) оқуды модельдеу", "C) білімді модельдеу", "D) пайымдауды модельдеу"], "answer": 2}, {"q": "4. Әртүрлі тапсырмаларды шешу кезінде адамның ойлау логикасына ұқсас компьютерлік программалар жасау", "options": ["A) интеллектті модельдеу", "B) оқуды модельдеу", "C) білімді модельдеу", "D) пайымдауды модельдеу"], "answer": 3}, {"q": "5. ЖИ жүйесінің жадындағы білімді формалдауға және көрсетуге байланысты мәселелер шешілетін жасанды интеллект бағыты", "options": ["A) қарым-қатынас", "B) білімді ұсыну", "C) қабылдау", "D) білімге сүйеніп, іс-әрекеттерді орындау"], "answer": 1}, {"q": "6. Білімді толық емес сипаттамалар негізінде толықтыру тәсілдері әзірленетін жасанды интеллект бағыты", "options": ["A) қарым-қатынас", "B) білімді ұсыну", "C) қабылдау", "D) білімге сүйеніп, іс-әрекеттерді орындау"], "answer": 3}, {"q": "7. Табиғи тілдегі байланысқан мәтіндерді түсіну мен синтездеу мәселесі жататын жасанды интеллект бағыты", "options": ["A) қарым-қатынас", "B) білімді ұсыну", "C) қабылдау", "D) білімге сүйеніп, іс-әрекеттерді орындау"], "answer": 0}, {"q": "8. ЖИ жүйелеріндегі ішкі ұғымдарға негізделген көріністерді жасауға арналған құралдарды әзірлеу әдістері кіретін жасанды интеллект бағыты", "options": ["A) қарым-қатынас", "B) тәртіп", "C) қабылдау", "D) оқыту"], "answer": 2}, {"q": "9. Бастапқы тапсырманың декомпозициясын неғұрлым ұсақ әрі ЖИ жүйелері үшін белгілі әдістерге көшіретін жасанды интеллект бағыты", "options": ["A) қарым-қатынас", "B) тәртіп", "C) қабылдау", "D) оқыту"], "answer": 3}, {"q": "10. ЖИ жүйелерімен және адамдармен тиісті дәрежеде әрекет жасауға мүмкіндік беретін реттелген рәсімдер әзірлеу қажет жасанды интеллект бағыты", "options": ["A) қарым-қатынас", "B) тәртіп", "C) қабылдау", "D) оқыту"], "answer": 1}, {"q": "11. Жасанды интеллектіні білім беру жүйесінде қолданудағы болашағы бар бағыттардың бірі", "options": ["A) жеке оқыту", "B) бейімдеп оқыту", "C) аралық интервалдық оқыту", "D) кері байланыс"], "answer": 1}, {"q": "12. Статистикалық есептерге арналған әмбебап құрал", "options": ["A) жасанды интеллект", "B) машиналық оқыту", "C) виртуалды машина", "D) нейрондық желі"], "answer": 0}, {"q": "13. Аурудың қандай да бір белгілері, емделушінің сыртқы түрі, талдау нәтижелері", "options": ["A) шығу деректері", "B) кіру деректері", "C) өңдеу деректері", "D) оқу деректері"], "answer": 1}, {"q": "14. Дәрігер өз тәжірибесі мен біліміне сүйене отырып, деректерді өңдейді әрі соған сүйеніп, диагноз қояды", "options": ["A) шығу деректері", "B) кіру деректері", "C) өңдеу деректері", "D) оқу деректері"], "answer": 0}, {"q": "15. Жүйе көптеген мысалдарды өңдейді, заңдылықтарды анықтайды әрі жаңа деректердің сипаттамасын болжау үшін, оларды қолданады", "options": ["A) жасанды интеллект", "B) машиналық оқыту", "C) виртуалды машина", "D) нейрондық желі"], "answer": 1}, {"q": "16. Мәшинелік оқытудың математикалық негізіне жатпайды", "options": ["A) статистика", "B) сызықтық алгебра", "C) геометрия", "D) стереометрия", "E) информатика", "F) оңтайландыру теориясы"], "answers": [2, 3]}, {"q": "17. Әртүрлі белгілердің негізінде категориялық жауапты, яғни белгілі кластарға жататын нысандарды болжау", "options": ["A) кластерлеу", "B) регрессия есептері", "C) жіктеу есебі", "D) нормадан ауытқуды анықтау есебі"], "answer": 2}, {"q": "18. Қандай да бір агрументтерге тәуелді функцияның қандай да бір мәнін анықтайды", "options": ["A) кластерлеу", "B) регрессия есептері", "C) жіктеу есебі", "D) нормадан ауытқуды анықтау есебі"], "answer": 1}, {"q": "19. Регрессия түрлері", "options": ["A) пәндік", "B) полиномиалды", "C) қызметтік", "D) дискретті", "E) сызықтық", "F) векторлық"], "answers": [1, 4]}, {"q": "20. Деректердің дұрыс жауаптармен, яғни белгілермен берілуі ерекшелігі болатын оқыту", "options": ["A) негіздеп оқыту", "B) мұғалімсіз оқыту", "C) мұғаліммен оқыту", "D) мұғалімнің жартылай қатысуымен оқыту"], "answer": 2}, {"q": "21. Жүйе пайдалы белгілерді алып, оларды талдай отырып, осы деректердегі заңдылықтарды өз бетінше табуға тырысады", "options": ["A) негіздеп оқыту", "B) мұғалімсіз оқыту", "C) мұғаліммен оқыту", "D) мұғалімнің жартылай қатысуымен оқыту"], "answer": 1}, {"q": "22. Нысандар жиынтығы, оларды топтастырып, ұқсас нысандар тобын табу керек", "options": ["A) кластерлеу", "B) регрессия есептері", "C) жіктеу есебі", "D) нормадан ауытқуды анықтау есебі"], "answer": 0}, {"q": "23. Белгілердің негізінде ауытқуды ауытқымаудан ажыратуды үйрену, яғни бір нысанның басқа нысанға ұқсамайтынын анықтап, белгілеу қажет", "options": ["A) кластерлеу", "B) регрессия есептері", "C) жіктеу есебі", "D) нормадан ауытқуды анықтау есебі"], "answer": 3}, {"q": "24. Бұл әдіс деректермен маңызды белгілерді алу немесе барлық нысандарды белгілеу қиын болғанда тиімді", "options": ["A) негіздеп оқыту", "B) мұғалімсіз оқыту", "C) мұғаліммен оқыту", "D) мұғалімнің жартылай қатысуымен оқыту"], "answer": 3}, {"q": "25. Жүйе қандай да бір ортамен өзара әрекет ете отырып оқытылатын оқыту", "options": ["A) негіздеп оқыту", "B) мұғалімсіз оқыту", "C) мұғаліммен оқыту", "D) мұғалімнің жартылай қатысуымен оқыту"], "answer": 0}, {"q": "26. Белгілердің тәуелсіздігі туралы жорамалы бар Байес теоремасына негізделген жіктеу алгоритмі", "options": ["A) K-жақын көршілер әдісі", "B) нормадан ауытқуды анықтау есебі", "C) қарапайым байес алгоритмі", "D) кластерлеу"], "answer": 2}, {"q": "27. Байес теоремасында берілген кластың априорлық ықтималдығы", "options": ["A) P(x|c)", "B) P(x)", "C) P(c)", "D) P(c|x)"], "answer": 2}, {"q": "28. Байес теоремасында берілген класс кезінде берілген мәннің ықтималдығы", "options": ["A) P(x|c)", "B) P(x)", "C) P(c)", "D) P(c|x)"], "answer": 0}, {"q": "29. Байес теоремасында белгінің берілген мәнінің априорлық ықтималдығы", "options": ["A) P(x|c)", "B) P(x)", "C) P(c)", "D) P(c|x)"], "answer": 1}, {"q": "30. Байес теоремасында x белгісінің берілген мәні кезіндегі с берілген класының апостериорлық ықтималдығы", "options": ["A) P(x|c)", "B) P(x)", "C) P(c)", "D) P(c|x)"], "answer": 3}, {"q": "31. Алгоритм барлық бақылаулар арасынан бұрын белгісіз жаңа нысанға ұқсайтын k белгілі нысандарды бөліп алуға қабілетті", "options": ["A) K-жақын көршілер әдісі", "B) нормадан ауытқуды анықтау есебі", "C) қарапайым байес алгоритмі", "D) кластерлеу"], "answer": 0}, {"q": "32. Мәшинелік оқытудың бірнеше алгоритмінен тұратын алгоритм", "options": ["A) ансамбльдеу", "B) жіктеу", "C) ансамбль", "D) регрессия"], "answer": 2}, {"q": "33. Ансамбльді құру процесі", "options": ["A) ансамбльдеу", "B) жіктеу", "C) ансамбль", "D) регрессия"], "answer": 0}, {"q": "34. Адамның жүйке жүйесінің көшірмесін алуға негізделген жасанды интеллект саласындағы бағыттардың бірі", "options": ["A) жасанды интеллект", "B) машиналық оқыту", "C) виртуалды машина", "D) нейрондық желі"], "answer": 3}, {"q": "35. Ағзаның қоршаған ортаға бейімделуін реттейтін күрделі желі", "options": ["A) жасанды интеллект", "B) машиналық оқыту", "C) виртуалды машина", "D) нейрондық желі"], "answer": 3}, {"q": "36. Өзара әрекеттесетін жасанды нейрондар жиынтығы", "options": ["A) синапис", "B) жасанды нейрондық желі", "C) жасырын қабат", "D) нейрон"], "answer": 1}, {"q": "37. Ақпаратты қабылдап алатын, онымен қарапайым есептеулер жасап, әрі қарай тарататын есептеу бірлігі", "options": ["A) синапис", "B) жасанды нейрондық желі", "C) жасырын қабат", "D) нейрон"], "answer": 3}, {"q": "38. Бір нейронның шығысы, екіншісінің кірісі түйісетін жер, онда сигнал күшейеді немесе әлсірейді", "options": ["A) синапис", "B) жасанды нейрондық желі", "C) жасырын қабат", "D) нейрон"], "answer": 0}, {"q": "39. Нейрондық желілердің артықшылықтары", "options": ["A) шешімді бірнеше кезеңнен қабылдау", "B) жауап әрдайым шамалап беріледі", "C) өзгерістерге бейімделу", "D) шамадан тыс шапшаңдық", "E) шешімді таңдау себебін түсіндіру", "F) төзімділігі"], "answers": [2, 3, 5]}, {"q": "40. Нейрондық желілердің кемшіліктері", "options": ["A) шешімді бірнеше кезеңнен қабылдау", "C) кіріс деректерінің шуына төзімділік", "B) жауап әрдайым шамалап беріледі", "D) шамадан тыс шапшаңдық", "F) белгісіз заңдылықтар кезінде есептерді шығару", "E) шешімді таңдау себебін түсіндіру"], "answers": [0, 2, 5]}, {"q": "41. Әрбір нейрон - кішкентай процессор, сигнал нейрондармен бір уақытта өңделеді", "options": ["A) шешімді бірнеше кезеңнен қабылдау", "B) жауап әрдайым шамалап беріледі", "C) кіріс деректерінің шуына төзімділік", "D) шамадан тыс шапшаңдық"], "answer": 3}, {"q": "42. Жасанды нейрондық желілер деректерді оқып, қашан да ортаға бейімделеді", "options": ["A) төзімділігі", "B) белгісіз заңдылықтар кезінде есептерді шығару", "C) кіріс деректерінің шуына төзімділік", "D) өзгерістерге бейімделу"], "answer": 3}, {"q": "43. Нейрондық желілер дәл әрі нақты жауаптар бере алмайды", "options": ["A) шешімді таңдау себебін түсіндіру", "B) жауап әрдайым шамалап беріледі", "C) шешімді бірнеше кезеңмен қабылдау", "D) кіріс деректерінің шуына төзімділік"], "answer": 1}, {"q": "44. Жасанды нейрожелілердің нейрондары, жалпы, бір-біріне тәуелді емес. Олар жай ғана сигнал алады, оны түрлендіріп, сигналды әрі қарай береді", "options": ["A) шешімді таңдау себебін түсіндіру", "B) жауап әрдайым шамалап беріледі", "C) шешімді бірнеше кезеңмен қабылдау", "D) кіріс деректерінің шуына төзімділік"], "answer": 2}, {"q": "45. Кіріс сигналдарының тиісті салмақтарына көбейтілген қосындысы", "options": ["A) қате", "B) өлшенген сома", "C) белсендіру функциясы", "D) орташа квадраттық ауытқу"], "answer": 1}, {"q": "46. Өлшенген соманы аргумент ретінде қабылдайтын функция", "options": ["A) қате", "B) өлшенген сома", "C) белсендіру функциясы", "D) орташа квадраттық ауытқу"], "answer": 2}, {"q": "47. Ең негізгі белсендіру функциялары", "options": ["A) математикалық функция", "B) сызықтық функциясы", "C) бірреттік секіру функциясы", "D) квадраттық функция", "E) сигмоид функциясы", "F) дискретті функция"], "answers": [2, 4]}, {"q": "48. Белсендіру функциясының ең қарапайым түрі", "options": ["A) математикалық функция", "B) сызықтық функциясы", "C) бірреттік секіру функциясы", "D) сигмоид функциясы"], "answer": 2}, {"q": "49. Нейрондық желі оқытылатын деректер жиынтығы", "options": ["A) оқыту іріктелімі", "B) қате", "C) итерация", "D) кезең"], "answer": 0}, {"q": "50. Нейрондық желі арқылы өткен оқыту іріктемелерінің жалпы саны", "options": ["A) оқыту іріктелімі", "B) қате", "C) итерация", "D) кезең"], "answer": 2}, {"q": "51. Нейрондық желіні жүктеу кезінде бұл шама “0” деп белгіленіп, қолмен бапталады", "options": ["A) оқыту іріктелімі", "B) қате", "C) итерация", "D) кезең"], "answer": 3}, {"q": "52. Күтілетін жауап пен алынған жауаптың арасындағы айырмашылықты көрсететін шама", "options": ["A) оқыту іріктелімі", "B) қате", "C) итерация", "D) кезең"], "answer": 1}, {"q": "53. Барлық кіріс элементтері тікелей шығыс элементтерімен біріккен желі", "options": ["A) көпқабатты нейрондық желі", "B) персептрон желі", "C) кері байланысы жоқ желілер", "D) тікелей таралу желілері"], "answer": 1}, {"q": "54. Кіріс пен шығыстан және олардың арасындағы бір жасырын нейрон қабаттарынан тұратын нейрондық желі", "options": ["A) көпқабатты нейрондық желі", "B) персептрон желі", "C) кері байланысы жоқ желілер", "D) тікелей таралу желілері"], "answer": 0}, {"q": "55. Сигнал тек кірістен шығыс қабатына таралатын жасанды нейрондық желілер", "options": ["A) көпқабатты нейрондық желі", "B) персептрон желі", "C) кері байланысы жоқ желілер", "D) тікелей таралу желілері"], "answer": 3}, {"q": "56. Нейронның шығуы қайтадан кіру жолына берілетін жасанды нейрондық желілер", "options": ["A) көпқабатты нейрондық желі", "B) кері байланысты желілер", "C) кері байланысы жоқ желілер", "D) тікелей таралу желілері"], "answer": 1}, {"q": "57. Кіріс белгісі өткеннен кейін бізге қажетті шығысқа желі бойынша өзгеруі мен салмақты коэффициенттерді теріп іздеуі", "options": ["A) машиналық оқыту", "B) мұғаліммен оқыту", "C) нейрондық желіні оқыту", "D) негіздеп оқыту"], "answer": 2}, {"q": "58. Белгілі бір шарттарға негізделген дұрыс шешім қабылдауға мүмкіндік беретін үлгі", "options": ["A) дендриттер", "B) нейрожелі", "C) аксон", "D) синапс"], "answer": 1}, {"q": "59. Нейронның ұзын, созылған бөлігі, жүйке талшығы", "options": ["A) дендриттер", "B) нейрожелі", "C) аксон", "D) синапс"], "answer": 2}, {"q": "60. Ақпараттың кіріс порты", "options": ["A) дендриттер", "B) нейрожелі", "C) аксон", "D) синапс"], "answer": 0}, {"q": "61. Машиналық оқытудың құраушылары", "options": ["A) болжау", "B) деректер", "C) тану", "D) алгоритм", "E) ерекше белгілері", "F) жіктеу"], "answers": [1, 3, 4]}, {"q": "62. Машиналық оқытудың негізгі түрлері", "options": ["A) нейрожелілер", "B) кластерлеу", "C) қосымша ақпараттарды қолдану негізінде оқыту", "D) регрессия", "E) жіктеу", "F) классикалық оқыту"], "answers": [0, 2, 5]}, {"q": "63. Объектілердің қандай да бір критерийлері бойынша бөлінуі", "options": ["A) жіктеу", "B) регрессия", "C) кластерлеу", "D) ассоциация"], "answer": 0}, {"q": "64. Жоғары деңгейдегі нақты ерекше белгілері бойынша жинақтау", "options": ["A) жіктеу", "B) жалпылау", "C) кластерлеу", "D) ассоциация"], "answer": 1}, {"q": "65. Бұл алдын ала белгісіз деректерді кластер бойынша жіктеу", "options": ["A) жіктеу", "B) регрессия", "C) кластерлеу", "D) ассоциация"], "answer": 2}, {"q": "66. Деректерді параметрлер бойынша бөлу", "options": ["A) жіктеу", "B) болжау", "C) тану", "D) жалпылау"], "answer": 0}, {"q": "67. Деректер негізінде зерттеу объектісінің болашақ жағдайы туралы пайымдау", "options": ["A) жіктеу", "B) болжау", "C) тану", "D) жалпылау"], "answer": 1}, {"q": "68. Қазіргі уақытта нейрондық желілердің ең көп қолданылатын әдісі", "options": ["A) жіктеу", "B) болжау", "C) тану", "D) жалпылау"], "answer": 2}, {"q": "69. Компьютер адам миының нейрондық желілеріне ұқсас үлкен мөлшерде жасанды нейрондық желіні қалыптастырады", "options": ["A) негіздеп оқыту", "B) классикалық оқыту", "C) тереңдетілген оқыту", "D) машиналық оқыту"], "answer": 2}, {"q": "70. Кездейсоқ жолмен қате функциясының минимумын іздейтін алгоритм", "options": ["A) генетикалық", "B) градиенттік", "C) стохастикалық", "D) нейропакет"], "answer": 2}]'::jsonb, now() + interval '11 seconds');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, '№14 ТЕОРИУМ: IT Startup, Blockchain', '[{"q": "1. Ауқымды бизнес-модельді іздеу мен іске асыруға арналған уақытша құрылым", "options": ["A) краудфандинг", "B) стартап", "C) блокчейн", "D) нейрожелілер"], "answer": 1}, {"q": "2. Стартаптың жұмыс модельін құру орындалатын стартап кезеңі", "options": ["A) pre-seed", "B) seed", "C) прототип", "D) альфа-нұсқа"], "answer": 2}, {"q": "3. Бұл кезеңде инвесторларды іздей бастау керек", "options": ["A) pre-seed", "B) seed", "C) прототип", "D) альфа-нұсқа"], "answer": 1}, {"q": "4. Әзірлеушілердің болашақ тұтынушыларға не қажет екені туралы нақты идеясы мен түсінігінің болуы", "options": ["A) pre-seed", "B) seed", "C) прототип", "D) альфа-нұсқа"], "answer": 0}, {"q": "5. Осы кезеңде түзетулер енгізіліп, жобаның жұмыс үлгісінің ақаулары жойылады", "options": ["A) pre-seed", "B) seed", "C) прототип", "D) альфа-нұсқа"], "answer": 3}, {"q": "6. Нарықты зерттеу, кезең-кезеңмен жоспар құру, іске қосуға дайындық", "options": ["A) pre-seed", "B) seed", "C) прототип", "D) альфа-нұсқа"], "answer": 1}, {"q": "7. Идеяны іске асыру жоспары болмайтын кезең", "options": ["A) pre-seed", "B) seed", "C) прототип", "D) альфа-нұсқа"], "answer": 0}, {"q": "8. Өнім дайын, бірақ сынақтан өткізу және кемшіліктерді анықтау үшін оны шағын топ қала қолданатын кезең", "options": ["A) pre-seed", "B) ашық-бета нұсқа", "C) жабық-бета нұсқа", "D) альфа-нұсқа"], "answer": 3}, {"q": "9. Инвесторлар мен коммерциялық серіктестер де табылатын кезең", "options": ["A) pre-seed", "B) ашық-бета нұсқа", "C) жабық-бета нұсқа", "D) альфа-нұсқа"], "answer": 2}, {"q": "10. Қолданушылар белсенді түрде тартылатын, жоба кең ауқымда таралатын кезең", "options": ["A) pre-seed", "B) ашық-бета нұсқа", "C) жабық-бета нұсқа", "D) альфа-нұсқа"], "answer": 1}, {"q": "11. Өнімнің функционалды мәртебесі бар, тартылған бөгде қолданушылардың саны шектеулі кезең", "options": ["A) pre-seed", "B) ашық-бета нұсқа", "C) жабық-бета нұсқа", "D) альфа-нұсқа"], "answer": 2}, {"q": "12. Клиенттермен шарт жасалады, қызмет көрсетіліп, өнім сатылса бастайтын кезең", "options": ["A) pre-seed", "B) ашық-бета нұсқа", "C) жабық-бета нұсқа", "D) альфа-нұсқа"], "answer": 1}, {"q": "13. Белгілі бір деңгейде шетелдік компаниялардың көшірмелері болатын қазақстандық жобалар кіретін топ", "options": ["A) жаулап алышулар", "B) сәтті көшірмелер", "C) күмәнділер", "D) инвесторлар"], "answer": 1}, {"q": "14. Жаңашыл болғандықтан, болашағы айқын емес стартаптар", "options": ["A) жаулап алышулар", "B) сәтті көшірмелер", "C) күмәнділер", "D) инвесторлар"], "answer": 2}, {"q": "15. Нарықтың қандай да бір сегментін басып алуға, одан бәсекелес компанияларды ығыстыруға бағытталған стартаптар", "options": ["A) жаулап алышулар", "B) сәтті көшірмелер", "C) күмәнділер", "D) инвесторлар"], "answer": 0}, {"q": "16. Кез келген ниет білдірушіден белгілі бір жобаны қаржыландыру үшін, қаражат алудың бір түрі", "options": ["A) краудфандинг", "B) стартап", "C) блокчейн", "D) нейрожелілер"], "answer": 0}, {"q": "17. Ақша жинайтындар", "options": ["A) донор", "B) демеуші", "C) реципиенттер", "D) инвесторлар"], "answer": 2}, {"q": "18. Ақша беретіндер", "options": ["A) авторлар", "B) демеуші", "C) реципиенттер", "D) қатысушылар"], "answer": 1}, {"q": "19. Қоғам немесе нақты адамдар үшін пайдалы идея бар, алайда оны іске асыруға ақша жоқ краудфандинг жүргізу қағидасы", "options": ["A) жоба жоспары", "B) компанияның жабылуы", "C) қаржы қажеттілігі", "D) краудфандинг үшін алаң таңдау"], "answer": 2}, {"q": "20. Белгіленген мерзім өткеннен кейін науқан жабылатын краудфандинг жүргізу қағидасы", "options": ["A) жоба жоспары", "B) компанияның жабылуы", "C) қаржы қажеттілігі", "D) краудфандинг үшін алаң таңдау"], "answer": 1}, {"q": "21. Қажетті соманы жинау үшін ұйымдастырушылар идеяны жобаға айналдырып, оның құнын белгілеп қоятын краудфандинг жүргізу қағидасы", "options": ["A) жоба жоспары", "B) компанияның жабылуы", "C) қаржы қажеттілігі", "D) краудфандинг үшін алаң таңдау"], "answer": 0}, {"q": "22. Жоба краудфандинг алаңына қойылатын краудфандинг жүргізу қағидасы", "options": ["A) жоба жоспары", "B) компанияның жабылуы", "C) қаржы қажеттілігі", "D) краудфандинг үшін алаң таңдау"], "answer": 3}, {"q": "23. Реципиенттердің географиялық жағдайына аса назар аудармайтын танымал сайт", "options": ["A) StartTime", "B) Indiegogo", "C) Kickstarter", "D) Baribirge"], "answer": 1}, {"q": "24. Жарнаманың тиімділігін арттыратын тауар не қызмет түрі туралы ақпарат жазылған бір реттік сайт", "options": ["A) лендинг", "B) email-маркетинг", "C) контент-маркетинг", "D) инфографика"], "answer": 0}, {"q": "25. Талап етілетін аудитория үшін өзіндік құндылығы бар контентті құру мен тарату", "options": ["A) лендинг", "B) email-маркетинг", "C) контент-маркетинг", "D) инфографика"], "answer": 2}, {"q": "26. Түрлі ақпаратты көрнекі түрде көрсету тәсілі", "options": ["A) лендинг", "B) email-маркетинг", "C) контент-маркетинг", "D) инфографика"], "answer": 3}, {"q": "27. Дәйекті тарих форматында күрделі деректерді ұсыну үшін, мәтін, суреттер мен дизайн элементтерін бір бүтінге біріктірудің тиімді тәсілі", "options": ["A) лендинг", "B) email-маркетинг", "C) контент-маркетинг", "D) инфографика"], "answer": 3}, {"q": "28. Белгілі бір уақыт ішінде болатын қандай да бір процесті, әрекетті сипаттайтын инфографика", "options": ["A) салыстырылатын инфографика", "B) инфографика-сценарий", "C) инфографика-схема", "D) инфорграфика-коллаж"], "answer": 1}, {"q": "29. Қандай да бір нәрсенің ішкі құрылымы, сипаттамалары мен ерекшелігі туралы баяндалған инфографика", "options": ["A) салыстырылатын инфографика", "B) инфографика-сценарий", "C) инфографика-схема", "D) инфорграфика-коллаж"], "answer": 2}, {"q": "30. Инфографиканың артықшылықтарына жатпайды", "options": ["A) адамның қабылдауына жеңіл", "B) вирустық әлеует", "C) сараптауды көрсету", "D) ақпарттың қолайлы түрде берілуі", "E) жасалуы оңай", "F) бренд танымалдығы"], "answer": 4}, {"q": "31. Бірегей жұмыс ұстанымы бар, деректерді және осы деректерді өңдеу туралы ақпаратты сақтау технологиясы", "options": ["A) майнинг", "B) блокчейн", "C) хэш-функция", "D) криптография"], "answer": 1}, {"q": "32. Ақпаратты құпияда ұстауға әрі жеке тұлғаны растауға мүмкіндік беретін математикалық әдістер", "options": ["A) майнинг", "B) блокчейн", "C) хэш-функция", "D) криптография"], "answer": 3}, {"q": "33. Ерекше математикалық функция", "options": ["A) майнинг", "B) блокчейн", "C) хэш-функция", "D) криптография"], "answer": 2}, {"q": "34. Кез келген ұзындықтағы еркін деректерді кіруге қабылдайды, қатаң түрде белгілі бір ұзындықтықтағы әріптер мен цифрлар тұрған жолды қайтарады", "options": ["A) майнинг", "B) блокчейн", "C) хэш-функция", "D) криптография"], "answer": 2}, {"q": "35. Кіру деректері қандай болатындығы маңызды емес, кез келген деректер үшін ұзындығы әрқашанда бірдей болатын хэш-функцияның қасиеті", "options": ["A) қайталамайтын", "B) бекітілген хэш көлемі", "C) болжауға болмайды", "D) коллизияның жоқтығы"], "answer": 1}, {"q": "36. Егер хабарлама болса, кез келген хэш біржақты болады", "options": ["A) қайталамайтын", "B) бекітілген хэш көлемі", "C) болжауға болмайды", "D) коллизияның жоқтығы"], "answer": 0}, {"q": "37. Екі әртүрлі хабарламаға бірдей хэш берілгенде, нәтиже болмайды", "options": ["A) қайталамайтын", "B) көшкінді нәтиже", "C) болжауға болмайды", "D) коллизияның жоқтығы"], "answer": 3}, {"q": "38. Кірген ақпараттағы кез келген өзгерістен мүлдем жаңа хэш пайда болады", "options": ["A) қайталамайтын", "B) көшкінді нәтиже", "C) болжауға болмайды", "D) коллизияның жоқтығы"], "answer": 1}, {"q": "39. Хэш бойынша ақпарат алуға болатын ешқандай алгоритм жоқ, тек хэш-функцияны қолданып, хэшті санау мүмкіндігі ғана бар", "options": ["A) қайталамайтын", "B) көшкінді нәтиже", "C) болжауға болмайды", "D) коллизияның жоқтығы"], "answer": 2}, {"q": "40. Блокчейннің қауіпсіз әрі маңызды екеніне кепілдік беру үшін, бір деңгейлі желіде бірлесіп жұмыс істейтін компьютерлер", "options": ["A) блоктар", "B) консенсус тетігі", "C) нодтар", "D) хэштер"], "answer": 2}, {"q": "41. Желінің программасын қосып, желідегі тораптармен келісілетін ережелер жиынтығы", "options": ["A) блоктар", "B) консенсус тетігі", "C) нодтар", "D) хэштер"], "answer": 1}, {"q": "42. Блокты блокчейнге өзгерту мүмкін болмайтындай етіп бекіту процесі", "options": ["A) майнинг", "B) блокчейн", "C) хэш-функция", "D) криптография"], "answer": 0}, {"q": "43. Кез келген қатысушы жүйедегі транзакцияларды бақылай алатын блокчейн артықшылығы", "options": ["A) сенімділік", "B) құпиялылық", "C) орталықсыздандыру", "D) толық ашықтық"], "answer": 3}, {"q": "44. Рұқсат етілмеген өзгерістерді енгізудің кез келген әрекеті алдыңғы көшірмелерге сәйкес келмегендіктен, қабылданбайтын блокчейн артықшылығы", "options": ["A) сенімділік", "B) құпиялылық", "C) орталықсыздандыру", "D) толық ашықтық"], "answer": 0}, {"q": "45. Деректерді сақтаудың басты сервері жоқ блокчейн артықшылығы", "options": ["A) сенімділік", "B) құпиялылық", "C) орталықсыздандыру", "D) ымыраласу"], "answer": 2}, {"q": "46. Барлық дерек шифрланған қалпында сақталатын блокчейн артықшылығы", "options": ["A) сенімділік", "B) құпиялылық", "C) орталықсыздандыру", "D) ымыраласу"], "answer": 1}, {"q": "47. Жүйеге қосылатын деректерді басқа қатысушылар тексереді, олар хэшті қайта есептейтін блокчейн артықшылығы", "options": ["A) сенімділік", "B) құпиялылық", "C) орталықсыздандыру", "D) ымыраласу"], "answer": 3}, {"q": "48. Ауқымды және тиімді бизнес-модельді табу үшін жасалған уақытша ұйым", "options": ["A) стартап", "B) блокчейн", "C) краудфандинг", "D) криптография"], "answer": 0}, {"q": "49. Бизнес-модельді сипаттайтын құжат", "options": ["A) бизнес-модель", "B) бизнес-жоспар", "C) операциялық модель", "D) масштабты модель"], "answer": 1}, {"q": "50. Нарықта пайдалануға арналған алдын ала жоспарланған іс-әрекеттердің реттілігі", "options": ["A) бизнес-модель", "B) бизнес-жоспар", "C) операциялық модель", "D) масштабты модель"], "answer": 0}, {"q": "51. Идеяларды және оларды жүзеге асыру әдістерін іздеу жүзеге асатын стартап даму кезеңі", "options": ["A) Startup Stage", "B) Pre-Seed Stage", "C) Growth Stage", "D) Expansion Stage"], "answer": 1}, {"q": "52. Бизнес-жоспарының мақсаттарына жету, жаңа нарықтарды игеру кезеңі", "options": ["A) Startup Stage", "B) Pre-Seed Stage", "C) Growth Stage", "D) Expansion Stage"], "answer": 3}, {"q": "53. Нарықтағы өнімге деген сұраныс, жоспарланған нарық орнын дамыту кезеңі", "options": ["A) Startup Stage", "B) Pre-Seed Stage", "C) Growth Stage", "D) Exit Stage"], "answer": 2}, {"q": "54. Инвестордың қатысуымен, өнімді нарыққа шығару кезеңі", "options": ["A) Startup Stage", "B) Pre-Seed Stage", "C) Growth Stage", "D) Exit Stage"], "answer": 0}, {"q": "55. Компанияның даму шыңына жету кезеңі", "options": ["A) Startup Stage", "B) Pre-Seed Stage", "C) Growth Stage", "D) Exit Stage"], "answer": 3}, {"q": "56. Флора мен фаунаның жойылып кету қаупі төнген түрлерін қорғайтын, мүмкіндігі шектеулі балалардың өмір сүру мүмкіндігін арттыру бойынша шешімдер ұсынатын компаниялар", "options": ["A) өтеусіз қорларға негізделген краудфандинг", "B) несиеге негізделген краудфандинг", "C) сыйақыға негізделген краудфандинг", "D) бизнестен өз үлесін алуға негізделген краудфандинг"], "answer": 0}, {"q": "57. АТ компаниясы өз жобасын осындай өнімнің көшірмесін эксклюзивті жаңартумен қаржыландыру үшін сыйақы ретінде ұсына алады", "options": ["A) өтеусіз қорларға негізделген краудфандинг", "B) несиеге негізделген краудфандинг", "C) сыйақыға негізделген краудфандинг", "D) бизнестен өз үлесін алуға негізделген краудфандинг"], "answer": 2}, {"q": "58. Инвестор өзі үшін қаржылық инвестициялар жиынтығын жасай отырып, бірнеше жобаға инвестиция сала алады", "options": ["A) өтеусіз қорларға негізделген краудфандинг", "B) несиеге негізделген краудфандинг", "C) сыйақыға негізделген краудфандинг", "D) бизнестен өз үлесін алуға негізделге